insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('cc000000-0000-0000-0000-000000000001', 'ukmla', '1347dc3a-3320-41ab-8dad-cc2d8dc77041',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('cc000000-0000-0000-0000-000000000001', 'A', 'Give intramuscular or intravenous benzylpenicillin (or IV ceftriaxone) immediately, before any transfer or investigation', true, 'Correct. This presentation (fever, meningism, non-blanching rash, shock) is classic for meningococcal meningitis/septicaemia, a medical emergency. Empirical antibiotics must be given immediately in the community or ED without waiting for investigations, as delay increases mortality.', 1),
('cc000000-0000-0000-0000-000000000001', 'B', 'Arrange an urgent CT head, and give antibiotics only once a lumbar puncture has confirmed the diagnosis', false, 'Ruled out because in suspected bacterial meningitis with signs of sepsis/shock, antibiotics must not be delayed for imaging or lumbar puncture; treatment is started immediately on clinical suspicion.', 2),
('cc000000-0000-0000-0000-000000000001', 'C', 'Start oral doxycycline while awaiting senior review', false, 'Ruled out because oral antibiotics have inadequate bioavailability and speed for this life-threatening presentation; parenteral antibiotics are required immediately.', 3),
('cc000000-0000-0000-0000-000000000001', 'D', 'Discharge with safety-netting advice and a follow-up GP appointment in 48 hours', false, 'Ruled out because this presentation is a medical emergency with signs of septic shock; discharge would risk rapid deterioration and death.', 4),
('cc000000-0000-0000-0000-000000000001', 'E', 'Give intravenous hydrocortisone alone and observe for improvement before considering antibiotics', false, 'Ruled out because steroids are an adjunct in some meningitis cases but never a substitute for immediate antibiotics, which are the priority intervention.', 5),
('cc000000-0000-0000-0000-000000000002', 'A', 'Withhold treatment until CSF herpes simplex virus PCR results are available', false, 'Ruled out because waiting for PCR confirmation delays treatment of a condition where early aciclovir significantly improves outcome; empirical treatment is started on clinical suspicion.', 1),
('cc000000-0000-0000-0000-000000000002', 'B', 'Start broad-spectrum antibiotics alone and reassess in 48 hours', false, 'Ruled out because antibiotics do not treat viral encephalitis; aciclovir is the specific and time-critical treatment needed here.', 2),
('cc000000-0000-0000-0000-000000000002', 'C', 'Start intravenous aciclovir immediately while awaiting CSF PCR results', true, 'Correct. Fever, altered behaviour/confusion, seizures, and temporal lobe changes on imaging are classic for herpes simplex encephalitis. IV aciclovir should be started empirically as soon as encephalitis is suspected, without waiting for CSF PCR confirmation, since delay worsens neurological outcome.', 3),
('cc000000-0000-0000-0000-000000000002', 'D', 'Arrange outpatient MRI brain and review in the neurology clinic in 2 weeks', false, 'Ruled out because this presentation is an acute neurological emergency requiring immediate inpatient treatment, not deferred outpatient assessment.', 4),
('cc000000-0000-0000-0000-000000000002', 'E', 'Give a loading dose of an antiepileptic alone, without antiviral therapy', false, 'Ruled out because although seizures may need treating, the priority is treating the underlying encephalitis with aciclovir; antiepileptics alone do not address the cause.', 5),
('cc000000-0000-0000-0000-000000000003', 'A', 'Glioblastoma multiforme', false, 'Ruled out because although gliomas can show ring enhancement, the acute febrile illness with a clear preceding infective source and systemic inflammatory features points to an infective rather than neoplastic cause.', 1),
('cc000000-0000-0000-0000-000000000003', 'B', 'Cerebral abscess', true, 'Correct. A ring-enhancing lesion on imaging with fever, headache, and focal neurological deficit, in a patient with a preceding source of infection (dental abscess) and diabetes (a risk factor), is classic for cerebral abscess.', 2),
('cc000000-0000-0000-0000-000000000003', 'C', 'Ischaemic stroke', false, 'Ruled out because ischaemic stroke typically causes sudden-onset deficit without fever or a ring-enhancing mass lesion, and does not follow a preceding dental infection in this way.', 3),
('cc000000-0000-0000-0000-000000000003', 'D', 'Multiple sclerosis relapse', false, 'Ruled out because MS demyelinating lesions are not typically ring-enhancing with mass effect and fever, and the age and history are atypical for a first MS presentation.', 4),
('cc000000-0000-0000-0000-000000000003', 'E', 'Migraine with aura', false, 'Ruled out because migraine does not cause fever, a structural ring-enhancing brain lesion, or persistent focal weakness.', 5),
('cc000000-0000-0000-0000-000000000004', 'A', 'Bacterial meningitis', false, 'Ruled out because bacterial meningitis typically shows a neutrophilic pleocytosis, low CSF glucose, and high protein, and patients are usually more unwell; this CSF pattern and clinical picture do not fit.', 1),
('cc000000-0000-0000-0000-000000000004', 'B', 'Tuberculous meningitis', false, 'Ruled out because TB meningitis typically has a more subacute/chronic course over weeks with very low CSF glucose and high protein, not this acute, mild presentation.', 2),
('cc000000-0000-0000-0000-000000000004', 'C', 'Subarachnoid haemorrhage', false, $x$Ruled out because SAH classically presents with sudden-onset severe 'thunderclap' headache and CSF would show xanthochromia/red cells, not a lymphocytic pleocytosis.$x$, 3),
('cc000000-0000-0000-0000-000000000004', 'D', 'Viral meningitis', true, 'Correct. A lymphocytic CSF pleocytosis with normal glucose and mildly raised protein, in a well-looking patient with a preceding viral illness and no rash or focal deficit, is typical of viral meningitis, which is usually self-limiting.', 4),
('cc000000-0000-0000-0000-000000000004', 'E', 'Fungal meningitis', false, 'Ruled out because fungal meningitis (e.g. cryptococcal) typically occurs in immunocompromised patients with a more indolent course, not a well immunocompetent young adult after a viral prodrome.', 5),
('cc000000-0000-0000-0000-000000000005', 'A', 'Primary CNS lymphoma', false, 'Ruled out because although this is an important differential in HIV with low CD4 count and can also show ring enhancement, toxoplasmosis is far more common and is the diagnosis to treat empirically first with a therapeutic trial before considering biopsy.', 1),
('cc000000-0000-0000-0000-000000000005', 'B', 'Bacterial cerebral abscess', false, 'Ruled out because bacterial abscess is less strongly associated with this specific pattern of multiple bilateral ring-enhancing lesions in the context of advanced HIV, where toxoplasmosis is far more likely.', 2),
('cc000000-0000-0000-0000-000000000005', 'C', 'Progressive multifocal leukoencephalopathy', false, 'Ruled out because PML typically causes non-enhancing white matter lesions without mass effect, not ring-enhancing mass lesions.', 3),
('cc000000-0000-0000-0000-000000000005', 'D', 'Cryptococcal meningoencephalitis', false, 'Ruled out because cryptococcal disease typically presents with meningitic features and raised intracranial pressure rather than discrete ring-enhancing mass lesions.', 4),
('cc000000-0000-0000-0000-000000000005', 'E', 'Cerebral toxoplasmosis', true, 'Correct. Multiple ring-enhancing brain lesions in a patient with advanced HIV and a low CD4 count (<200) is the classic presentation of cerebral toxoplasmosis, the most common cause of focal brain lesions in this population.', 5),
('cc000000-0000-0000-0000-000000000006', 'A', 'Delay all treatment until CT head has excluded a mass lesion', false, 'Ruled out because delaying empirical antibiotics for imaging in suspected bacterial meningitis increases mortality; antibiotics must be given promptly regardless of imaging timing.', 1),
('cc000000-0000-0000-0000-000000000006', 'B', 'Perform lumbar puncture before giving any antibiotics, to maximise diagnostic yield', false, 'Ruled out because in suspected bacterial meningitis, antibiotics should never be delayed for LP; antibiotics are given first if there is any delay in performing LP.', 2),
('cc000000-0000-0000-0000-000000000006', 'C', 'Treat as a first unprovoked seizure and discharge with neurology outpatient follow-up', false, 'Ruled out because the fever, neck stiffness, and photophobia indicate a likely CNS infection, which is a medical emergency requiring immediate treatment and admission, not discharge.', 3),
('cc000000-0000-0000-0000-000000000006', 'D', 'Start antiepileptic medication only and withhold antibiotics pending specialist review', false, 'Ruled out because the priority is treating the likely underlying meningitis with prompt antibiotics; antiepileptics do not address the cause and delaying antibiotics risks harm.', 4),
('cc000000-0000-0000-0000-000000000006', 'E', 'Start empirical IV antibiotics immediately, then proceed to lumbar puncture (CT head first only if specific contraindications are present)', true, 'Correct. This presentation is consistent with bacterial meningitis. Empirical antibiotics should not be delayed. In the absence of red flags for raised intracranial pressure (focal deficit, papilloedema, reduced GCS, or signs of herniation), lumbar puncture can proceed without CT; a seizure alone is not an absolute indication for CT before LP if the patient has recovered to GCS 15 with no focal signs.', 5),
('cc000000-0000-0000-0000-000000000007', 'A', 'Borrelia burgdorferi', true, 'Correct. A preceding erythema migrans rash after tick exposure, followed weeks later by neurological features (meningoencephalitis, cranial neuropathies), is characteristic of Lyme neuroborreliosis caused by Borrelia burgdorferi.', 1),
('cc000000-0000-0000-0000-000000000007', 'B', 'Herpes simplex virus', false, 'Ruled out because although HSV causes encephalitis, the history of tick exposure and a preceding erythema migrans rash points specifically to Lyme disease rather than HSV.', 2),
('cc000000-0000-0000-0000-000000000007', 'C', 'Neisseria meningitidis', false, 'Ruled out because meningococcal disease typically presents acutely with a non-blanching purpuric rash and rapid deterioration, not this subacute course following tick exposure with a resolved erythema migrans rash.', 3),
('cc000000-0000-0000-0000-000000000007', 'D', 'Mycobacterium tuberculosis', false, 'Ruled out because TB meningitis has a more chronic, insidious course over weeks without the characteristic antecedent tick bite and erythema migrans rash described here.', 4),
('cc000000-0000-0000-0000-000000000007', 'E', 'Enterovirus', false, 'Ruled out because although enterovirus is a common cause of viral meningitis, it does not explain the antecedent tick bites and erythema migrans rash, which are specific to Lyme disease.', 5),
('cc000000-0000-0000-0000-000000000008', 'A', 'Give rectal diazepam, as this is always the first-line route', false, 'Ruled out because rectal or buccal routes are used when IV access is not available; since IV access is already established here, IV lorazepam is the preferred first-line treatment.', 1),
('cc000000-0000-0000-0000-000000000008', 'B', 'Wait a further 10 minutes before intervening, as most seizures self-terminate', false, 'Ruled out because a seizure lasting over 5 minutes is defined as status epilepticus and requires prompt pharmacological treatment; further delay risks neuronal injury and increasing difficulty terminating the seizure.', 2),
('cc000000-0000-0000-0000-000000000008', 'C', 'Give IV phenytoin as the first-line agent', false, 'Ruled out because phenytoin (or other second-line agents like levetiracetam) is used if benzodiazepines fail to terminate the seizure, not as the first-line treatment.', 3),
('cc000000-0000-0000-0000-000000000008', 'D', 'Give IV lorazepam', true, 'Correct. A seizure lasting more than 5 minutes is defined as status epilepticus. With IV access already available, IV lorazepam is the first-line benzodiazepine treatment, given as the fastest and most effective route to terminate the seizure.', 4),
('cc000000-0000-0000-0000-000000000008', 'E', 'Perform an urgent lumbar puncture before giving any medication', false, 'Ruled out because the immediate priority in ongoing status epilepticus is terminating the seizure with a benzodiazepine; lumbar puncture is not part of first-line management and would dangerously delay treatment.', 5),
('cc000000-0000-0000-0000-000000000009', 'A', 'Vasovagal syncope', false, 'Ruled out because vasovagal syncope typically causes brief loss of consciousness with rapid recovery, without tongue biting or prolonged (20-minute) post-ictal confusion.', 1),
('cc000000-0000-0000-0000-000000000009', 'B', 'Generalised tonic-clonic seizure', true, 'Correct. The tonic phase (stiffening) followed by clonic rhythmic jerking, tongue biting, and a prolonged post-ictal confusional period are classic features distinguishing a generalised tonic-clonic seizure from other causes of collapse.', 2),
('cc000000-0000-0000-0000-000000000009', 'C', 'Cardiac syncope (e.g. arrhythmia)', false, 'Ruled out because cardiac syncope typically causes sudden collapse with rapid, complete recovery of consciousness, not prolonged post-ictal confusion or tongue biting.', 3),
('cc000000-0000-0000-0000-000000000009', 'D', 'Psychogenic non-epileptic attack', false, 'Ruled out because although this is an important differential, tongue biting and a clear prolonged post-ictal confusional state are more typical and specific for a true epileptic seizure.', 4),
('cc000000-0000-0000-0000-000000000009', 'E', 'Transient ischaemic attack', false, 'Ruled out because TIA causes focal neurological deficits without loss of consciousness or convulsive movements, which does not fit this presentation.', 5),
('cc000000-0000-0000-0000-000000000010', 'A', 'She should simply increase her dose of sodium valproate once pregnant to maintain seizure control', false, 'Ruled out because increasing valproate dose increases teratogenic risk further; the priority is to review and likely change the antiepileptic regimen before conception, not increase the teratogenic drug.', 1),
('cc000000-0000-0000-0000-000000000010', 'B', 'She should stop all antiepileptic medication immediately without medical advice, as pregnancy is more important than seizure control', false, 'Ruled out because abruptly stopping antiepileptics risks uncontrolled seizures, which themselves pose serious risks to mother and fetus; any change must be planned and supervised by a specialist.', 2),
('cc000000-0000-0000-0000-000000000010', 'C', 'She should be referred to a specialist to discuss switching to an alternative antiepileptic before conception, as sodium valproate carries a high risk of major congenital malformations and neurodevelopmental disorders', true, 'Correct. Sodium valproate is highly teratogenic (neural tube defects, congenital malformations) and is associated with neurodevelopmental disorders in children exposed in utero. It should not be used in women of childbearing potential unless no other effective treatment is available, and pre-conception specialist review is essential to plan a safer alternative.', 3),
('cc000000-0000-0000-0000-000000000010', 'D', 'No changes are needed as sodium valproate is safe throughout pregnancy', false, 'Ruled out because sodium valproate is one of the most teratogenic antiepileptic drugs and is specifically contraindicated in pregnancy where safer alternatives exist.', 4),
('cc000000-0000-0000-0000-000000000010', 'E', 'She should continue valproate but simply take high-dose folic acid instead of considering a medication switch', false, 'Ruled out because folic acid supplementation is recommended for women on antiepileptics, but it does not eliminate the substantial teratogenic and neurodevelopmental risks of valproate; a specialist medication review is still required.', 5),
('cc000000-0000-0000-0000-000000000011', 'A', 'He must not drive and must inform the DVLA; he can usually only resume driving a car once he has been seizure-free for 12 months', true, 'Correct. UK DVLA rules require a person with epilepsy to be seizure-free for 12 months (or have only had seizures during sleep for 3 years, if that pattern is established) before resuming driving a standard car licence; he has a legal duty to inform the DVLA of the diagnosis.', 1),
('cc000000-0000-0000-0000-000000000011', 'B', 'He can resume driving immediately since his seizures are now controlled on medication', false, 'Ruled out because DVLA regulations require a defined seizure-free period (usually 12 months) after diagnosis/last seizure before driving can resume, regardless of current control on medication.', 2),
('cc000000-0000-0000-0000-000000000011', 'C', 'He does not need to inform the DVLA as long as he feels well', false, 'Ruled out because there is a legal obligation to inform the DVLA of a diagnosis of epilepsy or any condition causing seizures, irrespective of how the patient feels.', 3),
('cc000000-0000-0000-0000-000000000011', 'D', 'He can resume driving after 3 months if his EEG is normal', false, 'Ruled out because DVLA rules are based on a defined period of seizure freedom (typically 12 months), not on EEG findings at an arbitrary earlier timepoint.', 4),
('cc000000-0000-0000-0000-000000000011', 'E', 'He should continue driving but avoid long journeys', false, $x$Ruled out because any driving is prohibited until the DVLA's seizure-free criteria are met; there is no allowance for limited or short-distance driving in the interim.$x$, 5),
('cc000000-0000-0000-0000-000000000012', 'A', 'Complex focal (impaired awareness) seizures', false, 'Ruled out because focal seizures with impaired awareness usually last longer, are often preceded by an aura, and are followed by post-ictal confusion, which is absent here.', 1),
('cc000000-0000-0000-0000-000000000012', 'B', 'Daydreaming/inattention due to a psychological cause', false, 'Ruled out because although this may be considered, the highly stereotyped, brief, frequent nature of the episodes with amnesia for the event is characteristic of a seizure disorder and warrants EEG assessment before assuming a psychological cause.', 2),
('cc000000-0000-0000-0000-000000000012', 'C', 'Narcolepsy with cataplexy', false, 'Ruled out because narcolepsy causes excessive daytime sleepiness and sudden sleep episodes, and cataplexy causes loss of muscle tone, neither of which matches this brief staring episode without tone loss.', 3),
('cc000000-0000-0000-0000-000000000012', 'D', 'Absence seizures', true, 'Correct. Brief episodes of blank staring with abrupt cessation of activity, no loss of tone, no post-ictal confusion, and rapid return to baseline are characteristic of absence seizures, typically seen in childhood/adolescence.', 4),
('cc000000-0000-0000-0000-000000000012', 'E', $x$Todd's paresis$x$, false, $x$Ruled out because Todd's paresis is a transient focal weakness following a focal seizure, not a staring/blank episode itself.$x$, 5),
('cc000000-0000-0000-0000-000000000013', 'A', 'A new focal seizure with post-ictal cerebellar signs', false, 'Ruled out because the symptoms described (nystagmus, ataxia, dysarthria) are a persistent syndrome rather than a transient post-ictal state, and are the classic triad of phenytoin toxicity rather than a seizure phenomenon.', 1),
('cc000000-0000-0000-0000-000000000013', 'B', 'Multiple sclerosis relapse', false, 'Ruled out because the temporal relationship to starting a new interacting medication and the classic toxicity triad make phenytoin toxicity far more likely than a new demyelinating event.', 2),
('cc000000-0000-0000-0000-000000000013', 'C', 'Alcohol intoxication', false, 'Ruled out because there is no history given of alcohol use, and the clear temporal association with a new antibiotic and known phenytoin therapy points to a drug-level related cause.', 3),
('cc000000-0000-0000-0000-000000000013', 'D', 'Vestibular neuritis', false, 'Ruled out because vestibular neuritis causes vertigo and nystagmus but does not typically cause dysarthria and ataxia together, and does not explain the temporal link to a new interacting drug.', 4),
('cc000000-0000-0000-0000-000000000013', 'E', 'Phenytoin toxicity, likely precipitated by a drug interaction raising phenytoin levels', true, 'Correct. Nystagmus, ataxia, and dysarthria are classic features of phenytoin toxicity. A new interacting medication (many antibiotics, e.g. metronidazole or co-trimoxazole, inhibit phenytoin metabolism) can raise phenytoin levels into the toxic range even without a dose change, and this should prompt an urgent phenytoin level check.', 5),
('cc000000-0000-0000-0000-000000000014', 'A', 'Immediately load him with an additional antiepileptic drug intravenously', false, 'Ruled out because the seizure has already stopped (he is post-ictal, not actively seizing); the immediate priority is safety assessment (ABCDE) rather than acute anti-seizure medication, which is reserved for ongoing status epilepticus.', 1),
('cc000000-0000-0000-0000-000000000014', 'B', 'Arrange discharge home once he is talking, with no further assessment needed', false, 'Ruled out because a change in seizure pattern/frequency (found unresponsive, apparently unwitnessed onset) with reported poor medication adherence warrants full assessment, including checking for a treatable precipitant and reviewing adherence, before discharge.', 2),
('cc000000-0000-0000-0000-000000000014', 'C', 'Assess and manage using an ABCDE approach, ensuring airway protection and checking blood glucose, while placing him in the recovery position if still drowsy', true, 'Correct. Immediately after a seizure, the priority is a structured ABCDE assessment: protecting the airway, checking oxygenation, and checking capillary blood glucose to exclude hypoglycaemia as a cause or complication, with the patient placed in the recovery position if reduced consciousness persists.', 3),
('cc000000-0000-0000-0000-000000000014', 'D', 'Perform a lumbar puncture immediately to look for infection', false, 'Ruled out because there is no fever or signs suggesting CNS infection here; the immediate priority is the ABCDE approach and basic bedside tests (including glucose), not an invasive procedure.', 4),
('cc000000-0000-0000-0000-000000000014', 'E', 'Withhold all further carbamazepine due to concern about seizure breakthrough', false, 'Ruled out because stopping antiepileptic medication would increase seizure risk further; poor adherence should be explored and addressed, not treated by stopping the drug.', 5),
('cc000000-0000-0000-0000-000000000015', 'A', 'MRI brain with contrast', false, 'Ruled out because non-contrast CT head is the first-line, most readily available and highly sensitive investigation for suspected acute subarachnoid haemorrhage; MRI is not the first-line emergency investigation.', 1),
('cc000000-0000-0000-0000-000000000015', 'B', 'Non-contrast CT head', true, $x$Correct. Sudden-onset, maximal-at-onset ('thunderclap') headache is the classic presentation of subarachnoid haemorrhage until proven otherwise. Non-contrast CT head performed promptly (ideally within 6 hours of onset) is the first-line investigation, as it is highly sensitive for detecting subarachnoid blood in this timeframe.$x$, 2),
('cc000000-0000-0000-0000-000000000015', 'C', 'Lumbar puncture immediately, before any imaging', false, 'Ruled out because CT head should be performed first to exclude a mass lesion or raised intracranial pressure and to look for blood; if CT is negative but clinical suspicion remains, LP (looking for xanthochromia) is performed subsequently, ideally after 12 hours from symptom onset.', 3),
('cc000000-0000-0000-0000-000000000015', 'D', 'Outpatient MRI brain in 2 weeks', false, 'Ruled out because this presentation requires emergency same-day investigation given the risk of a life-threatening subarachnoid haemorrhage; outpatient deferral is inappropriate and unsafe.', 4),
('cc000000-0000-0000-0000-000000000015', 'E', 'Temporal artery ultrasound', false, 'Ruled out because this investigation is used to assess for giant cell arteritis, which does not fit this thunderclap presentation in a 42-year-old without other GCA features.', 5),
('cc000000-0000-0000-0000-000000000016', 'A', 'Arrange a temporal artery biopsy and only start steroids if it is positive', false, 'Ruled out because starting steroids must not be delayed for biopsy confirmation in suspected GCA, given the risk of sudden vision loss; biopsy should ideally be done within days of starting steroids but treatment starts immediately.', 1),
('cc000000-0000-0000-0000-000000000016', 'B', 'Reassure the patient this is likely tension headache and advise simple analgesia', false, 'Ruled out because the combination of jaw claudication, scalp tenderness, and markedly raised inflammatory markers in an older patient is highly concerning for GCA, a vision-threatening emergency, not a benign tension headache.', 2),
('cc000000-0000-0000-0000-000000000016', 'C', 'Start a triptan and review in 2 weeks', false, 'Ruled out because triptans are used for migraine, not GCA, and delaying treatment risks irreversible visual loss.', 3),
('cc000000-0000-0000-0000-000000000016', 'D', 'Arrange outpatient MRI brain in 4 weeks', false, 'Ruled out because GCA is a medical emergency requiring immediate treatment with corticosteroids; a 4-week deferred outpatient imaging plan risks permanent blindness.', 4),
('cc000000-0000-0000-0000-000000000016', 'E', 'Start high-dose oral corticosteroids immediately, and arrange urgent same-day/next-day ophthalmology or rheumatology review with a temporal artery biopsy', true, 'Correct. This presentation (new headache, scalp tenderness, jaw claudication, raised inflammatory markers, and possible associated polymyalgia rheumatica symptoms) is classic for giant cell arteritis. High-dose corticosteroids should be started immediately on clinical suspicion, without waiting for biopsy, because of the risk of sudden irreversible vision loss.', 5),
('cc000000-0000-0000-0000-000000000017', 'A', 'Migraine with aura', false, 'Ruled out because migraine does not cause papilloedema or enlarged blind spots on visual field testing, and does not typically show this postural pattern with a normal CT but raised-ICP signs.', 1),
('cc000000-0000-0000-0000-000000000017', 'B', 'Cluster headache', false, 'Ruled out because cluster headache causes severe unilateral periorbital pain in short recurrent attacks with autonomic features, not the chronic postural headache and papilloedema seen here.', 2),
('cc000000-0000-0000-0000-000000000017', 'C', 'Cerebral venous sinus thrombosis', false, $x$Ruled out because although this can cause similar features and is an important differential to exclude (often with MR venography), the classic risk-factor profile and clinical picture here (obesity, young woman, COCP) is most typically idiopathic intracranial hypertension; venous sinus thrombosis should still be excluded during work-up but is not the single 'most likely' diagnosis given here.$x$, 3),
('cc000000-0000-0000-0000-000000000017', 'D', 'Idiopathic intracranial hypertension', true, 'Correct. Headache worse on lying/in the morning, visual disturbance, diplopia, papilloedema, and enlarged blind spots in an obese young woman with a normal CT are classic for idiopathic intracranial hypertension, caused by raised intracranial pressure without an identifiable structural cause.', 4),
('cc000000-0000-0000-0000-000000000017', 'E', 'Tension-type headache', false, 'Ruled out because tension headache does not cause papilloedema, enlarged blind spots, or diplopia, which indicate raised intracranial pressure rather than a primary tension headache.', 5),
('cc000000-0000-0000-0000-000000000018', 'A', 'Cluster headache', false, 'Ruled out because cluster headache causes much shorter (15-180 minute), excruciating unilateral periorbital attacks with autonomic features (lacrimation, ptosis, nasal congestion), typically without a visual aura of this type.', 1),
('cc000000-0000-0000-0000-000000000018', 'B', 'Tension-type headache', false, 'Ruled out because tension headache is typically bilateral, band-like, and not associated with visual aura, significant nausea, or marked photophobia/phonophobia.', 2),
('cc000000-0000-0000-0000-000000000018', 'C', 'Migraine with aura', true, 'Correct. Recurrent unilateral throbbing headache with nausea, photophobia/phonophobia, preceded by a visual aura (zigzag lines) lasting under an hour before headache onset, with a normal interictal examination, is classic for migraine with aura.', 3),
('cc000000-0000-0000-0000-000000000018', 'D', 'Transient ischaemic attack', false, 'Ruled out because the recurrent, stereotyped, monthly pattern over years with a typical migrainous aura and headache is not consistent with TIA, which would be a one-off vascular event rather than a chronic recurring pattern.', 4),
('cc000000-0000-0000-0000-000000000018', 'E', 'Trigeminal neuralgia', false, 'Ruled out because trigeminal neuralgia causes brief, electric shock-like facial pain in the trigeminal nerve distribution, not a throbbing headache with visual aura and associated nausea/photophobia.', 5),
('cc000000-0000-0000-0000-000000000019', 'A', 'High-flow 100% oxygen and/or subcutaneous triptan', true, 'Correct. This presentation (severe unilateral periorbital pain, autonomic features, restlessness, episodic clustering) is classic for cluster headache. First-line acute treatment is high-flow 100% oxygen via non-rebreathe mask and/or a subcutaneous or nasal triptan.', 1),
('cc000000-0000-0000-0000-000000000019', 'B', 'Oral paracetamol and codeine', false, 'Ruled out because simple oral analgesics are generally ineffective for cluster headache due to its rapid onset and severity; specific acute treatments (oxygen, triptan) are required.', 2),
('cc000000-0000-0000-0000-000000000019', 'C', 'Long-term daily prophylactic prednisolone with no acute treatment', false, 'Ruled out because although short courses of steroids can be used for prevention during a cluster bout, the question asks about acute attack treatment, for which oxygen/triptan is first-line; long-term daily steroids are not appropriate first-line management.', 3),
('cc000000-0000-0000-0000-000000000019', 'D', 'Intravenous mannitol', false, 'Ruled out because mannitol is used to reduce raised intracranial pressure in specific emergencies, not for treating cluster headache attacks.', 4),
('cc000000-0000-0000-0000-000000000019', 'E', 'Reassurance only, as symptoms will resolve spontaneously within a few minutes without treatment', false, 'Ruled out because although cluster headache attacks are self-limiting (typically 15-180 minutes), they cause severe distress and effective acute treatments (oxygen, triptan) should be offered rather than withholding treatment.', 5),
('cc000000-0000-0000-0000-000000000020', 'A', 'Progression to chronic migraine unrelated to medication use', false, 'Ruled out because although migraine can become chronic, the pattern of near-daily headache developing alongside heavy regular analgesic use strongly points to medication overuse headache as a major contributing/precipitating factor that should be addressed first.', 1),
('cc000000-0000-0000-0000-000000000020', 'B', 'Medication overuse headache', true, 'Correct. Frequent use of acute analgesics (particularly opioid-containing combinations like co-codamol, used on 10 or more days per month) in a patient with a pre-existing primary headache disorder is a classic cause of medication overuse headache, which presents as a chronic, near-daily headache that responds poorly to further analgesia.', 2),
('cc000000-0000-0000-0000-000000000020', 'C', 'New onset cluster headache', false, 'Ruled out because cluster headache causes brief, severe unilateral attacks with autonomic features, not a dull, near-daily headache pattern following heavy analgesic use.', 3),
('cc000000-0000-0000-0000-000000000020', 'D', 'Giant cell arteritis', false, 'Ruled out because there are no features here (jaw claudication, scalp tenderness, raised inflammatory markers, older age) to suggest GCA; the history is most consistent with medication overuse headache.', 4),
('cc000000-0000-0000-0000-000000000020', 'E', 'Idiopathic intracranial hypertension', false, 'Ruled out because there is no mention of papilloedema, visual disturbance, or postural headache pattern; the clear temporal link to heavy analgesic use points to medication overuse headache.', 5),
('cc000000-0000-0000-0000-000000000021', 'A', 'Lumbar puncture as the first investigation', false, 'Ruled out because lumbar puncture is contraindicated until a mass lesion causing raised intracranial pressure has been excluded by imaging, due to the risk of precipitating brain herniation.', 1),
('cc000000-0000-0000-0000-000000000021', 'B', 'Reassurance and simple analgesia, as headache is common after cancer treatment', false, 'Ruled out because the red-flag features (postural/positional worsening, straining-related worsening, papilloedema, visual disturbance) indicate raised intracranial pressure requiring urgent investigation, not reassurance.', 2),
('cc000000-0000-0000-0000-000000000021', 'C', 'Temporal artery biopsy', false, 'Ruled out because there are no features of giant cell arteritis (jaw claudication, scalp tenderness, typical age/inflammatory marker profile); the clinical picture instead suggests raised intracranial pressure from a likely mass lesion.', 3),
('cc000000-0000-0000-0000-000000000021', 'D', 'Outpatient ophthalmology review in 6 weeks for the papilloedema alone', false, 'Ruled out because this presentation requires urgent same-day/next-day neuroimaging given the risk of an underlying intracranial mass causing raised pressure; deferred outpatient review is unsafe.', 4),
('cc000000-0000-0000-0000-000000000021', 'E', 'Urgent MRI brain with contrast', true, 'Correct. Headache worse on waking/with coughing/straining, vomiting, and papilloedema are red-flag features of raised intracranial pressure, and in a patient with a history of malignancy this raises significant concern for brain metastases or another intracranial mass. Urgent contrast-enhanced MRI brain is the most appropriate investigation to identify a structural cause.', 5),
('cc000000-0000-0000-0000-000000000022', 'A', 'Essential tremor', false, 'Ruled out because essential tremor is typically bilateral, worse with action/intention (not at rest), and is not accompanied by bradykinesia, rigidity, or hypomimia.', 1),
('cc000000-0000-0000-0000-000000000022', 'B', 'Cerebellar disease', false, 'Ruled out because cerebellar tremor is an intention tremor (worse on reaching for a target) with associated ataxia, not a resting tremor with bradykinesia and rigidity.', 2),
('cc000000-0000-0000-0000-000000000022', 'C', $x$Parkinson's disease$x$, true, $x$Correct. Asymmetric resting tremor that improves with action, bradykinesia (small steps, reduced arm swing, hypomimia), and cogwheel rigidity form the classic triad (plus postural instability) of Parkinson's disease.$x$, 3),
('cc000000-0000-0000-0000-000000000022', 'D', 'Drug-induced parkinsonism', false, $x$Ruled out because there is no mention of a causative medication (e.g. antipsychotics, metoclopramide) in the history; the presentation is more consistent with idiopathic Parkinson's disease, and drug-induced parkinsonism is typically more symmetrical.$x$, 4),
('cc000000-0000-0000-0000-000000000022', 'E', 'Benign hereditary chorea', false, 'Ruled out because chorea consists of irregular, unpredictable jerky movements, not a resting tremor with bradykinesia and rigidity.', 5),
('cc000000-0000-0000-0000-000000000023', 'A', $x$Simple post-operative delirium unrelated to her Parkinson's medication$x$, false, $x$Ruled out because although delirium is common post-fracture, the specific combination of worsening rigidity, fever, and markedly raised CK following missed Parkinson's medication points specifically to a dopaminergic withdrawal crisis, which requires urgent medication reinstatement, not just general delirium management.$x$, 1),
('cc000000-0000-0000-0000-000000000023', 'B', 'Acute dopaminergic (levodopa) withdrawal causing a parkinsonism-hyperpyrexia syndrome', true, $x$Correct. Abrupt withdrawal or omission of dopaminergic medication in Parkinson's disease can precipitate a life-threatening parkinsonism-hyperpyrexia syndrome (akin to neuroleptic malignant syndrome), with rigidity, fever, confusion, and raised creatine kinase. This is an important, preventable complication of missed Parkinson's medications during hospital admission.$x$, 2),
('cc000000-0000-0000-0000-000000000023', 'C', 'Fat embolism syndrome', false, $x$Ruled out because fat embolism typically presents with respiratory distress, petechial rash, and confusion after long bone fracture, not the specific rigidity and CK rise linked to omitted Parkinson's medication.$x$, 3),
('cc000000-0000-0000-0000-000000000023', 'D', $x$New presentation of catatonia unrelated to Parkinson's disease$x$, false, $x$Ruled out because the clear temporal link to omission of her regular dopaminergic medication makes an acute Parkinson's medication withdrawal crisis far more likely than a new unrelated psychiatric diagnosis.$x$, 4),
('cc000000-0000-0000-0000-000000000023', 'E', 'Urinary sepsis alone', false, $x$Ruled out because although infection can cause fever and confusion, it does not explain the marked rigidity and CK rise, and the clear temporal association with missed Parkinson's medications is the key clue pointing to a withdrawal crisis.$x$, 5),
('cc000000-0000-0000-0000-000000000024', 'A', 'Neuroleptic malignant syndrome', true, $x$Correct. Fever, generalised 'lead-pipe' rigidity, confusion, autonomic instability, and markedly raised creatine kinase occurring after starting an antipsychotic (haloperidol) is classic for neuroleptic malignant syndrome, a life-threatening emergency.$x$, 1),
('cc000000-0000-0000-0000-000000000024', 'B', 'Serotonin syndrome', false, 'Ruled out because serotonin syndrome is typically associated with serotonergic drugs (SSRIs, MAOIs, tramadol) rather than antipsychotics, and features hyperreflexia/clonus/myoclonus more than the lead-pipe rigidity seen here; the clear antipsychotic trigger points to NMS.', 2),
('cc000000-0000-0000-0000-000000000024', 'C', 'Malignant hyperthermia', false, 'Ruled out because malignant hyperthermia is triggered by volatile anaesthetics or suxamethonium during general anaesthesia, not by antipsychotic medication started weeks earlier.', 3),
('cc000000-0000-0000-0000-000000000024', 'D', 'Acute dystonic reaction', false, 'Ruled out because acute dystonia causes sustained muscle contractions (e.g. oculogyric crisis, torticollis) typically within days of starting an antipsychotic, without the fever, autonomic instability, and marked CK rise of full NMS.', 4),
('cc000000-0000-0000-0000-000000000024', 'E', 'Meningoencephalitis', false, 'Ruled out because although fever and confusion overlap, the generalised rigidity, marked CK elevation, and clear temporal link to starting an antipsychotic make neuroleptic malignant syndrome far more likely than a primary CNS infection.', 5),
('cc000000-0000-0000-0000-000000000025', 'A', $x$Idiopathic Parkinson's disease$x$, false, $x$Ruled out because idiopathic Parkinson's disease typically presents with asymmetric tremor, a good sustained response to levodopa, and does not cause an early vertical supranuclear gaze palsy or prominent early falls.$x$, 1),
('cc000000-0000-0000-0000-000000000025', 'B', 'Multiple system atrophy', false, 'Ruled out because although this is a Parkinson-plus syndrome with poor levodopa response, MSA is characterised more by early and prominent autonomic failure (postural hypotension, urinary dysfunction) and cerebellar signs, rather than the specific vertical supranuclear gaze palsy described here.', 2),
('cc000000-0000-0000-0000-000000000025', 'C', 'Corticobasal degeneration', false, $x$Ruled out because corticobasal degeneration classically presents with markedly asymmetric limb rigidity/apraxia (e.g. 'alien limb' phenomenon), not the symmetrical parkinsonism and vertical gaze palsy described here.$x$, 3),
('cc000000-0000-0000-0000-000000000025', 'D', 'Progressive supranuclear palsy', true, $x$Correct. Early falls (especially backward falls), a vertical (particularly downward) supranuclear gaze palsy, axial rigidity, and poor levodopa response are the classic features distinguishing progressive supranuclear palsy from idiopathic Parkinson's disease.$x$, 4),
('cc000000-0000-0000-0000-000000000025', 'E', 'Vascular parkinsonism', false, 'Ruled out because vascular parkinsonism typically presents with a lower-body predominant gait disturbance related to cerebrovascular risk factors and imaging changes, not a supranuclear vertical gaze palsy.', 5),
('cc000000-0000-0000-0000-000000000026', 'A', 'Simple disease progression with no medication-related component', false, 'Ruled out because the clear temporal relationship to dosing intervals (worse before doses, dyskinesia after doses) specifically indicates motor fluctuations and dyskinesia related to levodopa pharmacokinetics, not just generic disease progression.', 1),
('cc000000-0000-0000-0000-000000000026', 'B', 'Acute dystonic reaction to levodopa', false, 'Ruled out because acute dystonia is a sustained abnormal posture typically seen with antipsychotic/antiemetic dopamine-blocking drugs, not the fluctuating wearing-off and peak-dose choreiform dyskinesia pattern described here.', 2),
('cc000000-0000-0000-0000-000000000026', 'C', 'Serotonin syndrome', false, $x$Ruled out because there is no mention of serotonergic drugs, and the clinical pattern described (predictable fluctuation with dosing) is the well-recognised phenomenon of motor fluctuations/dyskinesia in long-term Parkinson's treatment, not serotonin toxicity.$x$, 3),
('cc000000-0000-0000-0000-000000000026', 'D', $x$End-of-dose 'wearing off' with peak-dose dyskinesia$x$, true, $x$Correct. Worsening of parkinsonian symptoms towards the end of each levodopa dosing interval is classic 'wearing off', while the involuntary writhing movements occurring around the time of peak drug effect after dosing represent peak-dose dyskinesia — both are recognised long-term complications of levodopa therapy.$x$, 4),
('cc000000-0000-0000-0000-000000000026', 'E', 'Restless legs syndrome', false, 'Ruled out because restless legs syndrome causes an urge to move the legs, typically worse at rest/evening, not the specific dose-related motor fluctuation and peak-dose dyskinesia pattern described.', 5),
('cc000000-0000-0000-0000-000000000027', 'A', $x$Huntington's disease$x$, true, $x$Correct. Progressive chorea affecting limbs and face, combined with psychiatric/cognitive changes (irritability, concentration difficulty) and a strong family history suggestive of autosomal dominant inheritance, is classic for Huntington's disease.$x$, 1),
('cc000000-0000-0000-0000-000000000027', 'B', $x$Sydenham's chorea$x$, false, $x$Ruled out because Sydenham's chorea occurs in children/young people following streptococcal infection (rheumatic fever) and is self-limiting, not a progressive adult-onset condition with a strong family history.$x$, 2),
('cc000000-0000-0000-0000-000000000027', 'C', $x$Wilson's disease$x$, false, $x$Ruled out because although Wilson's disease can cause movement disorder and psychiatric symptoms in young adults, it typically presents with additional features (liver disease, Kayser-Fleischer rings) and is autosomal recessive, not matching this strong autosomal-dominant-pattern family history.$x$, 3),
('cc000000-0000-0000-0000-000000000027', 'D', 'Tardive dyskinesia', false, $x$Ruled out because tardive dyskinesia is caused by long-term antipsychotic use (typically orofacial dyskinesia), and there is no such drug history here; the family history strongly points to Huntington's disease.$x$, 4),
('cc000000-0000-0000-0000-000000000027', 'E', 'Benign essential tremor', false, 'Ruled out because essential tremor is a rhythmic tremor, not the irregular, jerky, dance-like chorea described, and does not explain the psychiatric changes or family history.', 5),
('cc000000-0000-0000-0000-000000000028', 'A', 'Increase the dose of metoclopramide to overcome the reaction', false, 'Ruled out because metoclopramide is the causative drug; increasing the dose would worsen the dystonic reaction rather than treat it. The causative drug should be stopped and an anticholinergic given.', 1),
('cc000000-0000-0000-0000-000000000028', 'B', 'IV lorazepam as first-line treatment', false, 'Ruled out because although benzodiazepines can sometimes be used adjunctively, the specific and most effective first-line treatment for an acute dystonic reaction is an anticholinergic agent such as procyclidine.', 2),
('cc000000-0000-0000-0000-000000000028', 'C', 'IV or IM procyclidine (an anticholinergic)', true, 'Correct. This presentation (oculogyric crisis with sustained upward eye deviation and torticollis) shortly after starting a dopamine-antagonist antiemetic (metoclopramide) is a classic acute dystonic reaction. Treatment is with an anticholinergic such as procyclidine, which usually produces rapid resolution.', 3),
('cc000000-0000-0000-0000-000000000028', 'D', 'Reassurance only, as the reaction will resolve without treatment within a few hours', false, 'Ruled out because although acute dystonic reactions can eventually resolve, they cause significant distress and can be dangerous (e.g. laryngeal dystonia affecting airway); prompt treatment with an anticholinergic is indicated rather than watchful waiting.', 4),
('cc000000-0000-0000-0000-000000000028', 'E', 'Urgent CT head to exclude a structural lesion', false, 'Ruled out because the clear temporal relationship to starting a dopamine-antagonist drug makes acute dystonic reaction the clinical diagnosis; imaging is not required first-line when the trigger and clinical picture are this characteristic.', 5),
('cc000000-0000-0000-0000-000000000029', 'A', 'Central retinal artery occlusion', false, 'Ruled out because CRAO causes sudden, painless, profound visual loss with a pale retina and cherry-red spot, not the subacute, painful presentation with disc swelling described here.', 1),
('cc000000-0000-0000-0000-000000000029', 'B', 'Anterior ischaemic optic neuropathy', false, $x$Ruled out because this typically occurs in older patients with vascular risk factors or giant cell arteritis, presenting with painless visual loss, which does not match this young patient's painful presentation.$x$, 2),
('cc000000-0000-0000-0000-000000000029', 'C', 'Acute angle-closure glaucoma', false, 'Ruled out because this causes a painful red eye with a fixed mid-dilated pupil and raised intraocular pressure, not the RAPD and disc swelling pattern described here.', 3),
('cc000000-0000-0000-0000-000000000029', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment typically presents with painless flashes, floaters, and a curtain-like visual field defect, not pain on eye movement with an RAPD and disc swelling.', 4),
('cc000000-0000-0000-0000-000000000029', 'E', 'Optic neuritis', true, 'Correct. Subacute unilateral visual loss with pain on eye movement, reduced colour vision, a relative afferent pupillary defect, and disc swelling is classic for optic neuritis, commonly due to demyelination and often the first presentation of multiple sclerosis.', 5),
('cc000000-0000-0000-0000-000000000030', 'A', 'Neuromyelitis optica spectrum disorder', false, 'Ruled out because although NMOSD can cause optic neuritis and myelitis and is an important differential requiring antibody testing (aquaporin-4), the presence of multiple periventricular brain lesions of different ages is more typical of MS; NMOSD lesions are more often longitudinally extensive on spinal MRI and brain MRI is often normal or atypical.', 1),
('cc000000-0000-0000-0000-000000000030', 'B', 'Relapsing-remitting multiple sclerosis', true, 'Correct. Two distinct clinical episodes (optic neuritis and now a myelitis) separated in time, plus MRI lesions disseminated in space (brain and spinal cord) and in time (lesions of different ages), fulfil the clinical picture of relapsing-remitting multiple sclerosis presenting with a further relapse causing transverse myelitis.', 2),
('cc000000-0000-0000-0000-000000000030', 'C', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes an ascending, predominantly peripheral (lower motor neuron) flaccid weakness with areflexia, not upper motor neuron signs (increased tone, brisk reflexes) with a clear sensory level and brain MRI lesions.', 3),
('cc000000-0000-0000-0000-000000000030', 'D', 'Subacute combined degeneration of the cord (B12 deficiency)', false, 'Ruled out because although this can cause myelopathy, it typically presents with dorsal column and corticospinal signs without a discrete sensory level, and does not explain the preceding separate optic neuritis episode or the disseminated brain lesions of different ages.', 4),
('cc000000-0000-0000-0000-000000000030', 'E', 'Motor neurone disease', false, 'Ruled out because MND does not cause sensory levels, and this history of a preceding optic neuritis with brain lesions of varying age fits multiple sclerosis, not a pure motor neurodegenerative disease.', 5),
('cc000000-0000-0000-0000-000000000031', 'A', 'Start a disease-modifying therapy immediately as the acute treatment for this relapse', false, 'Ruled out because disease-modifying therapies reduce the frequency of future relapses over the long term; they are not used to treat an acute relapse itself, for which corticosteroids are used.', 1),
('cc000000-0000-0000-0000-000000000031', 'B', 'Broad-spectrum antibiotics, as this is likely a urinary tract infection causing a pseudo-relapse', false, 'Ruled out because urinalysis is negative and she is afebrile, making infection less likely; the clinical picture instead reflects a genuine MS relapse, for which corticosteroids (not antibiotics) are the appropriate treatment.', 2),
('cc000000-0000-0000-0000-000000000031', 'C', 'Physiotherapy alone, with no medical treatment', false, 'Ruled out because although physiotherapy/rehabilitation supports recovery, corticosteroids are the recommended first-line treatment to shorten relapse duration and severity; physiotherapy alone is not sufficient initial management.', 3),
('cc000000-0000-0000-0000-000000000031', 'D', 'High-dose corticosteroids (e.g. oral or IV methylprednisolone) after excluding infection', true, 'Correct. This represents an acute MS relapse (new or worsening neurological symptoms lasting more than 24 hours, without infection or other cause). High-dose corticosteroids can shorten the duration and severity of a relapse and are appropriate first-line treatment once infection has been excluded, as here.', 4),
('cc000000-0000-0000-0000-000000000031', 'E', 'Urgent plasma exchange as first-line treatment', false, 'Ruled out because plasma exchange is reserved for severe relapses not responding to corticosteroids, not as first-line treatment for a typical relapse.', 5),
('cc000000-0000-0000-0000-000000000032', 'A', $x$Uhthoff's phenomenon$x$, false, $x$Ruled out because Uhthoff's phenomenon refers to worsening of existing neurological symptoms with heat/exercise (e.g. hot bath, fever), not an electric shock sensation on neck flexion.$x$, 1),
('cc000000-0000-0000-0000-000000000032', 'B', $x$Romberg's sign$x$, false, $x$Ruled out because Romberg's sign is increased postural sway/instability when a patient closes their eyes while standing, testing proprioceptive pathways, not an electric shock sensation on neck flexion.$x$, 2),
('cc000000-0000-0000-0000-000000000032', 'C', 'Babinski sign', false, 'Ruled out because the Babinski (plantar) response is an upgoing great toe with stroking of the sole, indicating an upper motor neuron lesion, unrelated to the electric shock sensation described.', 3),
('cc000000-0000-0000-0000-000000000032', 'D', 'Brown-Sequard syndrome', false, 'Ruled out because Brown-Sequard syndrome refers to a specific pattern of ipsilateral motor/dorsal column loss with contralateral spinothalamic loss from hemicord damage, not this specific neck-flexion-triggered sensory phenomenon.', 4),
('cc000000-0000-0000-0000-000000000032', 'E', $x$Lhermitte's sign$x$, true, $x$Correct. An electric shock-like sensation radiating down the spine (and sometimes into the limbs) on neck flexion is Lhermitte's sign, classically associated with cervical spinal cord demyelination in multiple sclerosis, though it can occur in other cervical cord pathologies.$x$, 5),
('cc000000-0000-0000-0000-000000000033', 'A', 'Oligoclonal IgG bands present in the CSF but not in the paired serum sample', true, 'Correct. Oligoclonal bands present in CSF but absent from a paired serum sample indicate intrathecal (within the CNS) synthesis of immunoglobulin, supporting a diagnosis of multiple sclerosis when combined with the appropriate clinical and MRI picture.', 1),
('cc000000-0000-0000-0000-000000000033', 'B', 'Markedly elevated CSF white cell count with neutrophil predominance', false, 'Ruled out because a neutrophilic pleocytosis suggests bacterial infection, not multiple sclerosis, which typically shows a normal or only mildly raised lymphocytic count.', 2),
('cc000000-0000-0000-0000-000000000033', 'C', 'Low CSF glucose relative to serum glucose', false, 'Ruled out because low CSF glucose is typical of bacterial or tuberculous meningitis, not multiple sclerosis, where CSF glucose is usually normal.', 3),
('cc000000-0000-0000-0000-000000000033', 'D', 'Markedly elevated CSF opening pressure', false, 'Ruled out because raised opening pressure is a feature of conditions like idiopathic intracranial hypertension or CNS infection, not a specific finding supporting a diagnosis of MS.', 4),
('cc000000-0000-0000-0000-000000000033', 'E', 'Xanthochromia on visual inspection of the CSF', false, 'Ruled out because xanthochromia indicates prior subarachnoid haemorrhage (breakdown products of blood), which is unrelated to multiple sclerosis.', 5),
('cc000000-0000-0000-0000-000000000034', 'A', 'A new true MS relapse', false, $x$Ruled out because a true relapse involves new or worsening symptoms lasting more than 24 hours that do not simply reverse with cooling; this reversible, heat-triggered pattern is characteristic of Uhthoff's phenomenon, not a new relapse.$x$, 1),
('cc000000-0000-0000-0000-000000000034', 'B', 'Medication side effect from her disease-modifying therapy', false, $x$Ruled out because the clear pattern of heat-triggered worsening with reversal on cooling is the classic description of Uhthoff's phenomenon, not a medication adverse effect.$x$, 2),
('cc000000-0000-0000-0000-000000000034', 'C', $x$Uhthoff's phenomenon$x$, true, $x$Correct. Temporary worsening of pre-existing MS symptoms with increased body temperature (heat, exercise, fever), which then reverses on cooling, is Uhthoff's phenomenon, a well-recognised feature of demyelinating disease reflecting temperature-sensitive nerve conduction in demyelinated axons.$x$, 3),
('cc000000-0000-0000-0000-000000000034', 'D', 'Progression to secondary progressive MS', false, 'Ruled out because secondary progressive MS involves a gradual, sustained accumulation of disability, not a transient, reversible, heat-related fluctuation in existing symptoms.', 4),
('cc000000-0000-0000-0000-000000000034', 'E', 'Anxiety-related functional symptoms', false, 'Ruled out because the specific, reproducible relationship to heat exposure with symptom reversal on cooling is a recognised physiological phenomenon in demyelinating disease, not a functional/psychological symptom.', 5),
('cc000000-0000-0000-0000-000000000035', 'A', 'Multiple sclerosis', false, 'Ruled out because MS spinal cord lesions are typically short-segment (less than 3 vertebral levels) and brain MRI usually shows periventricular white matter lesions; the longitudinally extensive cord lesion, more severe/bilateral visual loss, and positive aquaporin-4 antibody strongly favour NMOSD over MS.', 1),
('cc000000-0000-0000-0000-000000000035', 'B', 'Neuromyelitis optica spectrum disorder', true, 'Correct. Severe, often bilateral optic neuritis, a longitudinally extensive spinal cord lesion (spanning 3 or more vertebral segments), a relatively normal brain MRI, and positive aquaporin-4 antibodies are characteristic of neuromyelitis optica spectrum disorder, a distinct condition from MS requiring different long-term treatment.', 2),
('cc000000-0000-0000-0000-000000000035', 'C', 'Guillain-Barre syndrome', false, 'Ruled out because GBS is a peripheral, predominantly motor, ascending flaccid paralysis without a sensory level or optic nerve involvement, and does not relate to aquaporin-4 antibodies.', 3),
('cc000000-0000-0000-0000-000000000035', 'D', 'Subacute combined degeneration of the cord', false, 'Ruled out because this is due to vitamin B12 deficiency, presenting with dorsal column/corticospinal signs, not an antibody-mediated longitudinally extensive lesion with associated severe optic neuritis.', 4),
('cc000000-0000-0000-0000-000000000035', 'E', 'Transverse myelitis due to viral infection', false, 'Ruled out because although viral myelitis is a differential for an isolated cord lesion, the combination with severe optic neuritis and positive aquaporin-4 antibody specifically indicates neuromyelitis optica spectrum disorder.', 5),
('cc000000-0000-0000-0000-000000000036', 'A', 'Arterial blood gas as the sole marker of respiratory function', false, 'Ruled out because blood gases typically remain normal until respiratory failure is advanced in neuromuscular weakness; FVC is a more sensitive early marker of deteriorating respiratory muscle strength and is used to guide timing of intervention before gases decline.', 1),
('cc000000-0000-0000-0000-000000000036', 'B', 'Nerve conduction studies as the most urgent priority over respiratory monitoring', false, 'Ruled out because although nerve conduction studies support the diagnosis, the immediate priority in a patient with ascending weakness is monitoring for life-threatening respiratory muscle failure; this should not take priority over urgent respiratory monitoring.', 2),
('cc000000-0000-0000-0000-000000000036', 'C', 'Chest X-ray alone to assess respiratory status', false, 'Ruled out because chest X-ray does not assess respiratory muscle strength or reserve; FVC monitoring is the appropriate bedside test for tracking neuromuscular respiratory compromise.', 3),
('cc000000-0000-0000-0000-000000000036', 'D', 'Delay any respiratory assessment until he becomes breathless', false, 'Ruled out because waiting for breathlessness risks a rapid, life-threatening deterioration; regular proactive FVC monitoring is used to anticipate and pre-empt respiratory failure in Guillain-Barre syndrome.', 4),
('cc000000-0000-0000-0000-000000000036', 'E', 'Regular monitoring of forced vital capacity (FVC)', true, 'Correct. This presentation (ascending, symmetrical, areflexic weakness following a diarrhoeal illness, likely Campylobacter jejuni-related Guillain-Barre syndrome) carries a risk of respiratory muscle weakness and failure. Regular FVC monitoring is essential to detect deteriorating respiratory function early, before hypoxia develops, and to guide the need for ventilatory support.', 5),
('cc000000-0000-0000-0000-000000000037', 'A', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes a progressive, non-fluctuating ascending weakness with areflexia, not fatigable, activity-related ocular weakness that improves with rest.', 1),
('cc000000-0000-0000-0000-000000000037', 'B', 'Multiple sclerosis', false, 'Ruled out because although MS can cause diplopia, the classic pattern of fatigable, end-of-day-worsening ocular and eyelid weakness that improves with rest is specific to a neuromuscular junction disorder like myasthenia gravis, not MS.', 2),
('cc000000-0000-0000-0000-000000000037', 'C', 'Myasthenia gravis', true, 'Correct. Fatigable weakness that worsens with sustained activity and improves with rest, particularly affecting ocular muscles (ptosis, diplopia), with preserved sensation and reflexes, is classic for myasthenia gravis, an autoimmune disorder affecting the neuromuscular junction.', 3),
('cc000000-0000-0000-0000-000000000037', 'D', 'Lambert-Eaton myasthenic syndrome', false, 'Ruled out because although this is a differential, Lambert-Eaton syndrome classically causes weakness that improves (rather than worsens) with sustained repeated activity, and is strongly associated with underlying malignancy (e.g. small cell lung cancer); the pattern here of fatigability with rest-improvement is more typical of myasthenia gravis.', 4),
('cc000000-0000-0000-0000-000000000037', 'E', 'Motor neurone disease', false, 'Ruled out because MND causes progressive, non-fluctuating weakness with upper and lower motor neuron signs, not fatigable weakness that improves with rest.', 5),
('cc000000-0000-0000-0000-000000000038', 'A', 'Increase the dose of pyridostigmine alone and reassess in a few days', false, 'Ruled out because in a myasthenic crisis with respiratory compromise, simply increasing pyridostigmine is insufficient and unsafe; urgent escalation and specific crisis treatment (IVIG/plasma exchange) with critical care support are required.', 1),
('cc000000-0000-0000-0000-000000000038', 'B', 'Urgent escalation to critical care for close monitoring and consideration of ventilatory support, alongside specialist treatment (e.g. IVIG or plasma exchange)', true, 'Correct. This presentation is a myasthenic crisis, a life-threatening exacerbation of myasthenia gravis causing respiratory and bulbar weakness, often precipitated by infection or certain drugs (some antibiotics can worsen neuromuscular transmission). It requires urgent critical care involvement for close monitoring and potential ventilatory support, alongside specific treatments such as IVIG or plasma exchange.', 2),
('cc000000-0000-0000-0000-000000000038', 'C', 'Discharge home with an increased pyridostigmine dose and GP follow-up', false, 'Ruled out because falling vital capacity with bulbar and respiratory symptoms indicates a life-threatening myasthenic crisis requiring inpatient, likely critical care, management, not discharge.', 3),
('cc000000-0000-0000-0000-000000000038', 'D', 'Start high-dose oral corticosteroids alone as sole treatment, without escalation', false, 'Ruled out because although steroids can be used in myasthenia gravis management, in an acute crisis with respiratory compromise the priority is urgent escalation/monitoring and rapid-acting treatments like IVIG or plasma exchange; steroids alone are not adequate or fast enough for a crisis and can even transiently worsen weakness initially.', 4),
('cc000000-0000-0000-0000-000000000038', 'E', 'Stop pyridostigmine immediately with no further intervention', false, 'Ruled out because abruptly stopping pyridostigmine would likely worsen her weakness further; the priority is escalation and specific crisis management, not withdrawal of her usual treatment.', 5),
('cc000000-0000-0000-0000-000000000039', 'A', 'Ulnar nerve entrapment at the elbow', false, 'Ruled out because ulnar nerve lesions affect the little and ring fingers and cause weakness of finger abduction/adduction, not the thumb/index/middle finger (median nerve) distribution and thenar wasting described here.', 1),
('cc000000-0000-0000-0000-000000000039', 'B', 'Cervical radiculopathy (C6/C7)', false, 'Ruled out because although cervical radiculopathy can cause similar sensory symptoms, the specific nocturnal pattern relieved by shaking the hand, combined with thenar wasting, is much more typical of carpal tunnel syndrome (a peripheral nerve entrapment) than a cervical nerve root lesion.', 2),
('cc000000-0000-0000-0000-000000000039', 'C', 'Thoracic outlet syndrome', false, 'Ruled out because thoracic outlet syndrome typically causes more diffuse arm symptoms with vascular or lower brachial plexus (C8/T1) features, not the specific median nerve distribution and classic nocturnal relief-by-shaking pattern seen in carpal tunnel syndrome.', 3),
('cc000000-0000-0000-0000-000000000039', 'D', 'Carpal tunnel syndrome', true, 'Correct. Nocturnal numbness and tingling in the thumb, index, and middle fingers (the median nerve distribution), relieved by shaking the hand, with thenar wasting and weak thumb abduction, is classic for carpal tunnel syndrome due to median nerve compression at the wrist.', 4),
('cc000000-0000-0000-0000-000000000039', 'E', 'Peripheral diabetic neuropathy', false, $x$Ruled out because diabetic neuropathy is typically symmetrical and affects the distal lower limbs first ('glove and stocking'), not a focal unilateral median nerve distribution with thenar wasting.$x$, 5),
('cc000000-0000-0000-0000-000000000040', 'A', 'Motor neurone disease', true, 'Correct. A combination of both upper motor neuron (brisk reflexes, increased tone) and lower motor neuron (wasting, fasciculations) signs, with progressive limb and bulbar (swallowing, speech) involvement and entirely normal sensation, is the classic presentation of motor neurone disease.', 1),
('cc000000-0000-0000-0000-000000000040', 'B', 'Cervical spondylotic myelopathy', false, 'Ruled out because although this can cause mixed UMN/LMN signs, it does not typically cause bulbar symptoms (dysphagia, dysarthria) or such widespread fasciculations, and sensory changes are common, unlike the pure motor, normal-sensation picture here.', 2),
('cc000000-0000-0000-0000-000000000040', 'C', 'Multifocal motor neuropathy', false, 'Ruled out because this condition causes purely lower motor neuron signs (no upper motor neuron features), and does not typically cause bulbar symptoms in this pattern.', 3),
('cc000000-0000-0000-0000-000000000040', 'D', 'Peripheral neuropathy due to diabetes', false, 'Ruled out because diabetic neuropathy is typically sensorimotor with sensory symptoms and does not produce upper motor neuron signs (brisk reflexes, increased tone) as described here.', 4),
('cc000000-0000-0000-0000-000000000040', 'E', 'Multiple sclerosis', false, 'Ruled out because MS characteristically involves sensory pathways and would not present with this specific pure motor, symmetric, progressive UMN+LMN pattern with fasciculations and bulbar involvement without any sensory disturbance.', 5),
('cc000000-0000-0000-0000-000000000041', 'A', 'Diabetic peripheral neuropathy', true, $x$Correct. A symmetrical, distal, sensory-predominant neuropathy in a 'stocking' distribution with absent ankle reflexes, in a patient with long-standing poorly controlled diabetes, is classic for diabetic peripheral neuropathy, the most common cause of peripheral neuropathy in the UK.$x$, 1),
('cc000000-0000-0000-0000-000000000041', 'B', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes a rapidly progressive, predominantly motor, ascending weakness over days to weeks, not a slowly progressive sensory neuropathy over a year.', 2),
('cc000000-0000-0000-0000-000000000041', 'C', 'Vitamin B12 deficiency', false, 'Ruled out because although B12 deficiency causes peripheral neuropathy, this typically also involves prominent dorsal column signs (proprioception, ataxia) and sometimes upper motor neuron signs; the clear chronic history in a patient with long-standing poorly controlled diabetes makes diabetic neuropathy the most likely diagnosis, though B12 could be checked as part of work-up.', 3),
('cc000000-0000-0000-0000-000000000041', 'D', 'Charcot-Marie-Tooth disease', false, 'Ruled out because this is an inherited neuropathy that typically presents earlier in life with distal weakness and skeletal deformities (e.g. pes cavus), not an acquired, adult-onset sensory neuropathy clearly linked to long-standing poorly controlled diabetes.', 4),
('cc000000-0000-0000-0000-000000000041', 'E', 'Alcohol-related peripheral neuropathy', false, 'Ruled out because there is no history of alcohol excess given, and the strong association with long-standing, poorly controlled diabetes makes diabetic peripheral neuropathy the most likely cause.', 5),
('cc000000-0000-0000-0000-000000000042', 'A', 'Stroke affecting the facial motor cortex', false, $x$Ruled out because a central (upper motor neuron) facial palsy from stroke spares the forehead (frontalis muscle has bilateral cortical innervation), allowing the patient to still wrinkle their forehead; this patient cannot, indicating a lower motor neuron (peripheral) lesion, i.e. Bell's palsy, not stroke.$x$, 1),
('cc000000-0000-0000-0000-000000000042', 'B', 'Multiple sclerosis relapse', false, $x$Ruled out because although MS can rarely cause facial weakness, the classic, isolated lower motor neuron pattern with preceding post-auricular pain is far more consistent with Bell's palsy, and other supportive MS features are absent.$x$, 2),
('cc000000-0000-0000-0000-000000000042', 'C', $x$Bell's palsy (idiopathic lower motor neuron facial nerve palsy)$x$, true, $x$Correct. Unilateral facial weakness affecting the forehead (unable to wrinkle it, indicating a lower motor neuron pattern), with inability to close the eye, in the absence of other neurological signs, is classic for Bell's palsy, the most common cause of acute unilateral facial nerve palsy.$x$, 3),
('cc000000-0000-0000-0000-000000000042', 'D', 'Guillain-Barre syndrome (Miller Fisher variant)', false, 'Ruled out because this variant typically causes bilateral ophthalmoplegia and ataxia alongside areflexia, not an isolated unilateral facial nerve palsy without limb or eye movement involvement.', 4),
('cc000000-0000-0000-0000-000000000042', 'E', 'Myasthenia gravis', false, 'Ruled out because myasthenia gravis causes fatigable weakness, often bilateral ptosis and variable diplopia, not a sudden isolated unilateral lower motor neuron facial nerve palsy with forehead involvement.', 5),
('cc000000-0000-0000-0000-000000000043', 'A', 'Give aspirin 300 mg only, and withhold thrombolysis regardless of timing', false, 'Ruled out because within the appropriate time window and with no contraindications, thrombolysis (not aspirin alone) is the priority acute treatment for ischaemic stroke; aspirin is typically given after the thrombolysis decision/24-hour post-thrombolysis CT, or if thrombolysis is contraindicated or unavailable.', 1),
('cc000000-0000-0000-0000-000000000043', 'B', 'Delay treatment until an MRI brain is performed to confirm the diagnosis', false, 'Ruled out because non-contrast CT head is sufficient to exclude haemorrhage and proceed with thrombolysis; waiting for MRI would cause dangerous delay and reduce the chance of benefit from time-critical reperfusion therapy.', 2),
('cc000000-0000-0000-0000-000000000043', 'C', 'Start anticoagulation with a therapeutic dose of low molecular weight heparin', false, 'Ruled out because full-dose anticoagulation is not first-line treatment for acute ischaemic stroke and can increase haemorrhagic transformation risk; thrombolysis is the appropriate time-critical intervention here.', 3),
('cc000000-0000-0000-0000-000000000043', 'D', 'Reassure the family that his symptoms will likely resolve and arrange outpatient follow-up', false, 'Ruled out because this is an acute stroke, a medical emergency requiring immediate hospital-based intervention (thrombolysis and stroke unit admission), not outpatient management.', 4),
('cc000000-0000-0000-0000-000000000043', 'E', 'Urgent intravenous thrombolysis (alteplase), provided there are no contraindications', true, 'Correct. This is an acute ischaemic stroke presenting within the thrombolysis time window (typically within 4.5 hours of symptom onset), with haemorrhage excluded on CT. Provided there are no contraindications, urgent thrombolysis should be given as soon as possible to maximise the chance of good functional recovery, alongside consideration of thrombectomy if a large vessel occlusion is confirmed.', 5),
('cc000000-0000-0000-0000-000000000044', 'A', 'Reassure her that no further action is needed since her symptoms have fully resolved', false, 'Ruled out because a TIA carries a significant short-term risk of a subsequent full stroke; urgent assessment and secondary prevention (starting with aspirin) are required even though symptoms have resolved.', 1),
('cc000000-0000-0000-0000-000000000044', 'B', 'Start aspirin 300 mg immediately and refer for urgent specialist assessment (within 24 hours) and further investigation', true, 'Correct. This presentation is a transient ischaemic attack (TIA), a warning sign of stroke risk. Current guidance recommends immediate aspirin (unless contraindicated) and urgent specialist assessment within 24 hours of symptom onset, to identify and manage the underlying cause and reduce the risk of a subsequent full stroke.', 2),
('cc000000-0000-0000-0000-000000000044', 'C', 'Arrange routine outpatient neurology referral in 6 weeks', false, 'Ruled out because TIA requires urgent specialist assessment within 24 hours (not routine, delayed referral), given the significant early risk of stroke following a TIA.', 3),
('cc000000-0000-0000-0000-000000000044', 'D', 'Start warfarin immediately before any further investigation', false, 'Ruled out because anticoagulation is not started empirically without first establishing the cause (e.g. excluding haemorrhage, assessing for atrial fibrillation or carotid disease); aspirin is the appropriate immediate antiplatelet, with anticoagulation only added later if a specific indication such as AF is confirmed.', 4),
('cc000000-0000-0000-0000-000000000044', 'E', 'Advise her to attend her GP only if she has another similar episode', false, $x$Ruled out because a TIA requires prompt action now, not a 'wait and see' approach, due to the immediate elevated risk of stroke in the following days.$x$, 5),
('cc000000-0000-0000-0000-000000000045', 'A', 'Lifelong dual antiplatelet therapy alone, with no surgical intervention', false, 'Ruled out because although antiplatelet therapy is part of secondary prevention, significant symptomatic carotid stenosis of this degree warrants surgical referral for carotid endarterectomy, which has been shown to significantly reduce future stroke risk beyond medical therapy alone.', 1),
('cc000000-0000-0000-0000-000000000045', 'B', 'Anticoagulation with warfarin as the primary secondary prevention strategy', false, 'Ruled out because anticoagulation is not the standard treatment for large-artery atherosclerotic stroke due to carotid disease (unless there is a separate indication like atrial fibrillation); carotid endarterectomy plus antiplatelet therapy is the appropriate approach here.', 2),
('cc000000-0000-0000-0000-000000000045', 'C', 'Reassurance only, since he has already made a good clinical recovery', false, 'Ruled out because clinical recovery does not remove the ongoing risk of further stroke from significant carotid stenosis; carotid endarterectomy should still be pursued to reduce future risk.', 3),
('cc000000-0000-0000-0000-000000000045', 'D', 'Referral for carotid endarterectomy', true, 'Correct. Significant (greater than 70%, or 50% in some criteria) symptomatic carotid stenosis on the side corresponding to the stroke, in a patient who has made a good recovery, is an indication for carotid endarterectomy, ideally performed within 2 weeks of the event, to reduce the risk of further stroke.', 4),
('cc000000-0000-0000-0000-000000000045', 'E', 'Delay any intervention for at least 6 months to allow further neurological recovery', false, 'Ruled out because carotid endarterectomy is most beneficial when performed promptly (ideally within 2 weeks) after a symptomatic event; delaying intervention significantly reduces its benefit.', 5),
('cc000000-0000-0000-0000-000000000046', 'A', 'Urgent supportive care with careful blood pressure lowering per local protocol and neurosurgical/critical care referral', true, 'Correct. This is an acute large intracerebral haemorrhage with reduced consciousness and midline shift, a neurosurgical emergency. Immediate priorities include supportive ABCDE management, careful blood pressure control (rapid but controlled lowering per stroke guidance) to reduce further bleeding risk, and urgent neurosurgical/critical care input for consideration of surgical evacuation and management of raised intracranial pressure.', 1),
('cc000000-0000-0000-0000-000000000046', 'B', 'Immediate thrombolysis to treat the underlying vascular event', false, 'Ruled out because thrombolysis is absolutely contraindicated in haemorrhagic stroke, as it would worsen the bleeding; this is the opposite of the correct emergency response.', 2),
('cc000000-0000-0000-0000-000000000046', 'C', 'Give aspirin 300 mg immediately as for ischaemic stroke', false, 'Ruled out because antiplatelet therapy is contraindicated in acute intracerebral haemorrhage, as it would exacerbate bleeding; aspirin is used for ischaemic, not haemorrhagic, stroke.', 3),
('cc000000-0000-0000-0000-000000000046', 'D', 'Discharge for outpatient neurology follow-up once she is more alert', false, 'Ruled out because a large intracerebral haemorrhage with reduced GCS and midline shift is a life-threatening emergency requiring immediate inpatient (often neurosurgical/critical care) management, not discharge.', 4),
('cc000000-0000-0000-0000-000000000046', 'E', 'Withhold all blood pressure treatment to avoid reducing cerebral perfusion pressure', false, 'Ruled out because uncontrolled severe hypertension in acute intracerebral haemorrhage increases the risk of haematoma expansion; guideline-directed careful blood pressure lowering (not withholding treatment) is part of standard acute management.', 5),
('cc000000-0000-0000-0000-000000000047', 'A', 'Full-dose therapeutic anticoagulation with low molecular weight heparin immediately', false, 'Ruled out because routine early full-dose anticoagulation is not recommended after acute ischaemic stroke, due to increased risk of haemorrhagic transformation; antiplatelet therapy (aspirin) is the standard acute approach unless there is a specific indication (e.g. certain cardioembolic sources) guided by specialist advice.', 1),
('cc000000-0000-0000-0000-000000000047', 'B', 'No antiplatelet or anticoagulant therapy until 6 weeks post-stroke', false, 'Ruled out because early aspirin significantly reduces the risk of stroke recurrence and should be started promptly (once haemorrhage is excluded), not delayed for 6 weeks.', 2),
('cc000000-0000-0000-0000-000000000047', 'C', 'Dual antiplatelet therapy with aspirin and clopidogrel for one year', false, 'Ruled out because standard secondary prevention after most ischaemic strokes is aspirin for 2 weeks followed by long-term single-agent clopidogrel, rather than prolonged year-long dual antiplatelet therapy, which is reserved for specific higher-risk scenarios under specialist guidance.', 3),
('cc000000-0000-0000-0000-000000000047', 'D', 'Aspirin 300 mg daily for 2 weeks, then long-term secondary prevention antiplatelet therapy', true, 'Correct. Once haemorrhage has been excluded on imaging and the patient is not a candidate for thrombolysis (or has passed 24 hours post-thrombolysis), aspirin 300 mg daily should be started as soon as possible and continued for 2 weeks, after which long-term secondary prevention (typically clopidogrel) is used.', 4),
('cc000000-0000-0000-0000-000000000047', 'E', 'Intravenous unfractionated heparin infusion', false, 'Ruled out because routine heparin infusion is not standard therapy for acute ischaemic stroke secondary prevention and carries increased haemorrhage risk without proven benefit in this context.', 5),
('cc000000-0000-0000-0000-000000000048', 'A', 'Middle cerebral artery', false, 'Ruled out because MCA infarcts typically cause contralateral hemiparesis and hemisensory loss affecting the face and limbs together on one side (with cortical signs like dysphasia or neglect), not the crossed brainstem sensory pattern and cranial nerve signs described here.', 1),
('cc000000-0000-0000-0000-000000000048', 'B', 'Anterior cerebral artery', false, 'Ruled out because ACA infarcts typically cause contralateral leg-predominant weakness, not the brainstem/cranial nerve and crossed sensory pattern described here.', 2),
('cc000000-0000-0000-0000-000000000048', 'C', 'Anterior spinal artery', false, 'Ruled out because anterior spinal artery occlusion causes bilateral motor and spinothalamic sensory loss below the lesion with preserved dorsal columns, not the specific brainstem cranial nerve and crossed hemisensory pattern described here.', 3),
('cc000000-0000-0000-0000-000000000048', 'D', 'Basilar artery (locked-in syndrome)', false, 'Ruled out because basilar artery occlusion causing locked-in syndrome presents with quadriplegia and preserved consciousness with only vertical eye movements intact, a much more severe and different picture from the lateral medullary syndrome described here.', 4),
('cc000000-0000-0000-0000-000000000048', 'E', 'Posterior inferior cerebellar artery (lateral medullary syndrome)', true, 'Correct. Crossed sensory loss (ipsilateral facial sensory loss with contralateral limb pain/temperature loss), ipsilateral ataxia, vertigo, dysphagia, and diplopia are the classic features of lateral medullary (Wallenberg) syndrome, caused by posterior inferior cerebellar artery occlusion.', 5),
('cc000000-0000-0000-0000-000000000049', 'A', 'Withhold thrombolysis solely because he has a history of anticoagulant use, regardless of his current INR', false, 'Ruled out because a history of anticoagulant use is not itself a contraindication; what matters is the current INR/coagulation status, which here is 1.1 and within the acceptable range for thrombolysis.', 1),
('cc000000-0000-0000-0000-000000000049', 'B', 'Give full-dose warfarin immediately to restore anticoagulation before treating the stroke', false, 'Ruled out because the immediate priority in a time-critical ischaemic stroke is achieving reperfusion (thrombolysis) if eligible, not restoring long-term anticoagulation, which can be addressed after the acute stroke management decision.', 2),
('cc000000-0000-0000-0000-000000000049', 'C', 'Urgent intravenous thrombolysis, as his INR is within the safe range and he is within the treatment time window', true, 'Correct. He presents within the thrombolysis window with no haemorrhage on CT. Although his admission INR would usually need checking before thrombolysis in a patient on warfarin, an INR of 1.1 (essentially not therapeutically anticoagulated, consistent with his reported non-adherence) does not exceed the safe threshold, so thrombolysis can proceed without delay if otherwise eligible.', 3),
('cc000000-0000-0000-0000-000000000049', 'D', 'Delay treatment until a formal cardiology assessment of his mechanical valve is completed', false, 'Ruled out because this would cause a dangerous delay in time-critical stroke treatment; thrombolysis eligibility should be assessed and acted on promptly based on stroke-specific criteria (time window, CT findings, coagulation status).', 4),
('cc000000-0000-0000-0000-000000000049', 'E', 'Give aspirin 300 mg only and consider thrombolysis at a later time if symptoms worsen', false, 'Ruled out because he is currently eligible for thrombolysis within the time window with no exclusion on INR grounds; thrombolysis should not be deferred in favour of aspirin alone when time-critical reperfusion therapy is appropriate now.', 5),
('cc000000-0000-0000-0000-000000000050', 'A', 'Withhold anticoagulation because there is an associated infarct, treating this as for arterial ischaemic stroke with antiplatelets only', false, 'Ruled out because cerebral venous sinus thrombosis is managed with anticoagulation (not antiplatelets) even when a venous infarct (including haemorrhagic venous infarction) is present, as this is different from arterial stroke management.', 1),
('cc000000-0000-0000-0000-000000000050', 'B', 'Anticoagulation (e.g. with low molecular weight heparin), even in the presence of a venous infarct, alongside seizure management and specialist neurology input', true, 'Correct. Cerebral venous sinus thrombosis, here precipitated by the postpartum prothrombotic state, is treated with anticoagulation even when there is an associated venous infarct (which may have a haemorrhagic component), because anticoagulation reduces clot propagation and improves outcomes; this differs from the management of arterial ischaemic or primary haemorrhagic stroke.', 2),
('cc000000-0000-0000-0000-000000000050', 'C', 'Immediate thrombolysis with alteplase as for arterial ischaemic stroke', false, 'Ruled out because systemic thrombolysis is not the standard first-line treatment for cerebral venous sinus thrombosis; anticoagulation is the mainstay of treatment.', 3),
('cc000000-0000-0000-0000-000000000050', 'D', 'No specific treatment is required as this will resolve spontaneously post-partum', false, 'Ruled out because cerebral venous sinus thrombosis can cause significant morbidity and mortality if untreated, including raised intracranial pressure and further infarction/haemorrhage; active treatment with anticoagulation is required.', 4),
('cc000000-0000-0000-0000-000000000050', 'E', 'Discharge with routine postnatal follow-up in 6 weeks', false, 'Ruled out because this is an acute neurological emergency requiring immediate inpatient treatment and monitoring, not routine deferred outpatient follow-up.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('cc000000-0000-0000-0000-000000000001', 'Non-blanching purpuric rash plus fever and meningism strongly suggests meningococcal disease; treat as an emergency without waiting for confirmatory tests.', 1),
('cc000000-0000-0000-0000-000000000001', 'Empirical antibiotics (benzylpenicillin in primary care/pre-hospital, or IV ceftriaxone in hospital) should be given as soon as bacterial meningitis/meningococcal sepsis is suspected.', 2),
('cc000000-0000-0000-0000-000000000001', 'Lumbar puncture and CT are useful for confirmation and complications but must never delay first-dose antibiotics in a septic, deteriorating patient.', 3),
('cc000000-0000-0000-0000-000000000002', 'Herpes simplex encephalitis classically presents with fever, behavioural change/confusion, seizures, and temporal lobe involvement on imaging.', 1),
('cc000000-0000-0000-0000-000000000002', 'IV aciclovir should be started empirically as soon as encephalitis is suspected, without waiting for CSF PCR confirmation, because early treatment reduces mortality and morbidity.', 2),
('cc000000-0000-0000-0000-000000000002', 'Lumbar puncture with CSF PCR for HSV is used to confirm the diagnosis but should not delay first-dose aciclovir.', 3),
('cc000000-0000-0000-0000-000000000003', 'Cerebral abscess should be suspected with headache, fever, and focal neurology, especially with a preceding infective source (dental, sinus, ear, endocarditis) or immunocompromise/diabetes.', 1),
('cc000000-0000-0000-0000-000000000003', 'A ring-enhancing lesion with surrounding oedema on MRI/CT is the classic imaging appearance of an abscess.', 2),
('cc000000-0000-0000-0000-000000000003', 'Management requires urgent neurosurgical/infectious diseases input for antibiotics and often surgical drainage; lumbar puncture is often avoided due to risk of herniation.', 3),
('cc000000-0000-0000-0000-000000000004', 'Viral meningitis typically causes a lymphocytic CSF pleocytosis with normal glucose and mildly raised protein, in contrast to the neutrophilic, low-glucose picture of bacterial meningitis.', 1),
('cc000000-0000-0000-0000-000000000004', 'Patients with viral meningitis are usually less systemically unwell than those with bacterial meningitis and often improve with supportive care alone.', 2),
('cc000000-0000-0000-0000-000000000004', 'Red flags (rash, reduced consciousness, focal neurology, very high fever) should prompt treatment as bacterial until proven otherwise.', 3),
('cc000000-0000-0000-0000-000000000005', 'Multiple ring-enhancing lesions in an HIV patient with a low CD4 count (<200) should raise suspicion of cerebral toxoplasmosis first.', 1),
('cc000000-0000-0000-0000-000000000005', 'Primary CNS lymphoma is an important differential, especially with a single lesion or failure to respond to anti-toxoplasma treatment; a therapeutic trial of anti-toxoplasma therapy is often used before biopsy.', 2),
('cc000000-0000-0000-0000-000000000005', 'Advanced immunosuppression (low CD4 count) is the key risk factor that should be identified and prompt urgent HIV/infectious diseases specialist involvement.', 3),
('cc000000-0000-0000-0000-000000000006', 'Seizures can be a presenting feature of bacterial meningitis; fever, neck stiffness and photophobia should prompt urgent treatment as meningitis.', 1),
('cc000000-0000-0000-0000-000000000006', 'CT head before lumbar puncture is only required if there are signs of raised intracranial pressure or focal neurology (papilloedema, reduced GCS, focal deficit) — a single seizure with full recovery to GCS 15 is not itself an indication to delay LP.', 2),
('cc000000-0000-0000-0000-000000000006', 'Empirical antibiotics must never be delayed by imaging or lumbar puncture in suspected bacterial meningitis.', 3),
('cc000000-0000-0000-0000-000000000007', 'Erythema migrans (an expanding red/target-shaped rash at the bite site) following a tick bite is the hallmark early feature of Lyme disease, caused by Borrelia burgdorferi.', 1),
('cc000000-0000-0000-0000-000000000007', 'Neuroborreliosis (Lyme disease affecting the nervous system) can cause meningitis, cranial nerve palsies (especially facial nerve), and radiculopathy weeks after the initial infection.', 2),
('cc000000-0000-0000-0000-000000000007', 'A history of outdoor/wooded activity and tick exposure should prompt consideration of Lyme disease in unexplained neurological or febrile presentations.', 3),
('cc000000-0000-0000-0000-000000000008', 'Status epilepticus is defined as a seizure lasting 5 minutes or more, or recurrent seizures without recovery of consciousness between them.', 1),
('cc000000-0000-0000-0000-000000000008', 'First-line treatment is a benzodiazepine: IV lorazepam if IV access is available, or buccal midazolam/rectal diazepam if not.', 2),
('cc000000-0000-0000-0000-000000000008', 'If seizures continue despite two doses of benzodiazepine, second-line IV agents (e.g. levetiracetam, phenytoin, or sodium valproate) are used, and senior/anaesthetic input is required.', 3),
('cc000000-0000-0000-0000-000000000009', 'Tongue biting (especially lateral), a clear tonic-clonic movement pattern, and a prolonged post-ictal confusional state help distinguish epileptic seizures from syncope.', 1),
('cc000000-0000-0000-0000-000000000009', 'Vasovagal and cardiac syncope typically have rapid recovery of orientation, in contrast to the prolonged post-ictal confusion seen after generalised seizures.', 2),
('cc000000-0000-0000-0000-000000000009', 'A first seizure warrants assessment for underlying cause (ECG, bloods, consideration of imaging) and referral to a first-fit clinic; driving restrictions must be discussed.', 3),
('cc000000-0000-0000-0000-000000000010', 'Sodium valproate is teratogenic and is associated with neural tube defects, other congenital malformations, and neurodevelopmental disorders in children exposed in utero.', 1),
('cc000000-0000-0000-0000-000000000010', 'Women of childbearing potential on valproate should have pre-conception specialist review to discuss alternative antiepileptics; changes should be planned, not abrupt, given the risk of seizures from uncontrolled epilepsy.', 2),
('cc000000-0000-0000-0000-000000000010', 'High-dose folic acid (5 mg) is recommended pre-conception for women on antiepileptics but does not replace the need to minimise valproate exposure.', 3),
('cc000000-0000-0000-0000-000000000011', 'Patients with a diagnosis of epilepsy or seizures have a legal duty to inform the DVLA, and doctors should advise them of this responsibility and document the advice given.', 1),
('cc000000-0000-0000-0000-000000000011', 'For a standard car licence, patients generally must be seizure-free for 12 months before driving can resume (different, stricter rules apply to bus/lorry/vocational licences).', 2),
('cc000000-0000-0000-0000-000000000011', $x$This is a common ethical/legal responsibility scenario in UKMLA: the doctor's duty is to advise the patient to inform the DVLA themselves; breach of confidentiality by the doctor is only justified in specific circumstances where the patient refuses and continues driving despite advice.$x$, 3),
('cc000000-0000-0000-0000-000000000012', 'Absence seizures typically present in children/adolescents as brief (a few seconds), frequent episodes of blank staring with abrupt onset and offset and no post-ictal confusion.', 1),
('cc000000-0000-0000-0000-000000000012', 'EEG in absence seizures classically shows generalised 3 Hz spike-and-wave discharges.', 2),
('cc000000-0000-0000-0000-000000000012', 'First-line treatment for absence seizures is typically ethosuximide or sodium valproate (with lamotrigine as an alternative, particularly avoiding valproate in girls/women of childbearing potential where possible).', 3),
('cc000000-0000-0000-0000-000000000013', 'Phenytoin toxicity classically presents with a triad of nystagmus, ataxia, and dysarthria (progressing to confusion/drowsiness at higher levels).', 1),
('cc000000-0000-0000-0000-000000000013', 'Phenytoin has numerous drug interactions and a narrow therapeutic index with non-linear (zero-order) kinetics at higher doses, so small changes or interacting drugs can cause disproportionate rises in level.', 2),
('cc000000-0000-0000-0000-000000000013', 'Suspected phenytoin toxicity should prompt an urgent serum phenytoin level and review of any new interacting medications, rather than assuming a new neurological diagnosis.', 3),
('cc000000-0000-0000-0000-000000000014', 'Immediate post-seizure assessment follows an ABCDE approach: airway protection, oxygenation, and checking capillary blood glucose (hypoglycaemia can cause or mimic seizures).', 1),
('cc000000-0000-0000-0000-000000000014', 'Reduced consciousness after a seizure (post-ictal state) should prompt the recovery position and close monitoring until the patient returns to baseline.', 2),
('cc000000-0000-0000-0000-000000000014', 'Medication non-adherence is a common and important precipitant of breakthrough seizures in known epilepsy and should be explored as part of the assessment.', 3),
('cc000000-0000-0000-0000-000000000015', $x$Sudden-onset, maximal-at-onset ('thunderclap') headache should always be treated as subarachnoid haemorrhage until proven otherwise.$x$, 1),
('cc000000-0000-0000-0000-000000000015', 'Non-contrast CT head is the first-line investigation and is most sensitive when performed within 6 hours of headache onset.', 2),
('cc000000-0000-0000-0000-000000000015', 'If CT is negative but clinical suspicion remains, lumbar puncture (looking for xanthochromia) should be performed, ideally at least 12 hours after symptom onset to allow xanthochromia to develop.', 3),
('cc000000-0000-0000-0000-000000000016', 'Giant cell arteritis should be suspected in patients over 50 with new headache, scalp tenderness, jaw claudication, visual symptoms, and/or raised inflammatory markers (ESR/CRP), often with associated polymyalgia rheumatica.', 1),
('cc000000-0000-0000-0000-000000000016', 'High-dose corticosteroids should be started immediately on clinical suspicion to prevent irreversible visual loss, without waiting for temporal artery biopsy.', 2),
('cc000000-0000-0000-0000-000000000016', 'Any visual symptoms (amaurosis fugax, diplopia, visual loss) in suspected GCA constitute an ophthalmological emergency requiring same-day assessment.', 3),
('cc000000-0000-0000-0000-000000000017', 'Idiopathic intracranial hypertension classically occurs in obese women of childbearing age and presents with headache (worse lying down/in the morning), visual disturbance, papilloedema, and enlarged blind spots, with normal CT/MRI parenchyma.', 1),
('cc000000-0000-0000-0000-000000000017', 'Investigation should exclude a structural cause and cerebral venous sinus thrombosis (often via MR venography) before attributing raised intracranial pressure to idiopathic causes; lumbar puncture (after imaging) can confirm raised opening pressure and provide temporary relief.', 2),
('cc000000-0000-0000-0000-000000000017', 'Untreated papilloedema risks permanent visual loss, so any papilloedema found on fundoscopy warrants urgent ophthalmology/neurology referral for formal visual field assessment and management (weight loss, acetazolamide, or surgical options in refractory cases).', 3),
('cc000000-0000-0000-0000-000000000018', 'Migraine with aura features a reversible visual, sensory, or speech aura (commonly visual, e.g. zigzag lines/scotoma) typically lasting under 60 minutes, followed by or accompanying a throbbing headache with nausea and photophobia/phonophobia.', 1),
('cc000000-0000-0000-0000-000000000018', 'Diagnosis is clinical, based on history and a normal neurological examination; imaging is not routinely required for typical migraine presentations.', 2),
('cc000000-0000-0000-0000-000000000018', 'Migraine with aura is associated with a small increased stroke risk, which is an important consideration when prescribing the combined oral contraceptive pill (generally contraindicated).', 3),
('cc000000-0000-0000-0000-000000000019', 'Cluster headache is a trigeminal autonomic cephalalgia: severe unilateral periorbital pain with ipsilateral autonomic features (lacrimation, conjunctival injection, ptosis, nasal congestion), occurring in bouts of daily attacks, often with restlessness/agitation (contrasting with migraine, where patients prefer stillness).', 1),
('cc000000-0000-0000-0000-000000000019', 'First-line acute treatment is high-flow 100% oxygen and/or a subcutaneous or intranasal triptan; oral triptans are too slow given the short attack duration.', 2),
('cc000000-0000-0000-0000-000000000019', 'Verapamil is the mainstay for prevention during a cluster bout; short courses of corticosteroids can also be used to help break a cluster.', 3),
('cc000000-0000-0000-0000-000000000020', 'Medication overuse headache should be suspected in anyone with a pre-existing headache disorder who develops a chronic, near-daily headache while using acute analgesics frequently (opioids/triptans/combination analgesics on 10+ days/month, or simple analgesics on 15+ days/month).', 1),
('cc000000-0000-0000-0000-000000000020', 'Management involves withdrawing the overused medication (often causing a temporary worsening before improvement) alongside appropriate migraine prophylaxis.', 2),
('cc000000-0000-0000-0000-000000000020', 'Opioid-containing analgesics (e.g. co-codamol) are particularly likely to cause medication overuse headache and should generally be avoided for headache management.', 3),
('cc000000-0000-0000-0000-000000000021', 'Red-flag headache features include: worse on waking, worsened by coughing/straining/lying flat, associated vomiting, papilloedema, new focal neurology, and a history of malignancy — all indicating possible raised intracranial pressure.', 1),
('cc000000-0000-0000-0000-000000000021', 'In a patient with a history of cancer, new headache with raised-ICP features should prompt urgent imaging to look for brain metastases as a priority differential.', 2),
('cc000000-0000-0000-0000-000000000021', 'Lumbar puncture should not be performed until imaging has excluded a mass lesion, due to the risk of coning/herniation.', 3),
('cc000000-0000-0000-0000-000000000022', $x$The classic triad of Parkinson's disease is resting tremor (typically asymmetric, improves with voluntary movement), bradykinesia, and rigidity (often cogwheel), with postural instability appearing later.$x$, 1),
('cc000000-0000-0000-0000-000000000022', 'Bradykinesia manifests as small, shuffling steps, reduced arm swing, hypomimia (reduced facial expression), and micrographia.', 2),
('cc000000-0000-0000-0000-000000000022', 'Diagnosis is primarily clinical; a good, sustained response to levodopa supports the diagnosis and can help distinguish it from other parkinsonian syndromes.', 3),
('cc000000-0000-0000-0000-000000000023', $x$Parkinson's disease medications must never be omitted or delayed in hospital, including on the day of surgery, because abrupt withdrawal can precipitate a life-threatening parkinsonism-hyperpyrexia (acute akinetic) crisis resembling neuroleptic malignant syndrome.$x$, 1),
('cc000000-0000-0000-0000-000000000023', 'Features include severe rigidity, fever, autonomic instability, confusion, and markedly raised creatine kinase (risking rhabdomyolysis and renal failure).', 2),
('cc000000-0000-0000-0000-000000000023', $x$Nil-by-mouth status is not a reason to omit Parkinson's medication; alternative routes (dispersible levodopa via NG tube, rotigotine patch) should be used to avoid missed doses.$x$, 3),
('cc000000-0000-0000-0000-000000000024', 'Neuroleptic malignant syndrome typically develops within days to weeks of starting or increasing an antipsychotic (or after abrupt dopaminergic withdrawal) and presents with fever, lead-pipe rigidity, autonomic instability, and confusion.', 1),
('cc000000-0000-0000-0000-000000000024', 'Creatine kinase is markedly elevated, reflecting muscle breakdown, and can lead to rhabdomyolysis and acute kidney injury if untreated.', 2),
('cc000000-0000-0000-0000-000000000024', 'Management involves immediate cessation of the causative antipsychotic, supportive care/cooling and IV fluids, and consideration of dantrolene or bromocriptine in severe cases, usually with critical care input.', 3),
('cc000000-0000-0000-0000-000000000025', $x$Progressive supranuclear palsy is a 'Parkinson-plus' syndrome characterised by early postural instability/falls (classically backward falls), a vertical supranuclear gaze palsy, axial rigidity, and poor or minimal response to levodopa.$x$, 1),
('cc000000-0000-0000-0000-000000000025', $x$Parkinson-plus syndromes should be suspected when parkinsonism is accompanied by early falls, poor levodopa response, prominent early autonomic failure, cerebellar signs, or marked asymmetry/apraxia, distinguishing them from idiopathic Parkinson's disease.$x$, 2),
('cc000000-0000-0000-0000-000000000025', $x$Recognising a Parkinson-plus syndrome is important for prognosis and appropriate referral to specialist movement disorder services, as management and prognosis differ from idiopathic Parkinson's disease.$x$, 3),
('cc000000-0000-0000-0000-000000000026', $x$Long-term levodopa therapy is commonly complicated by motor fluctuations: 'wearing off' (return of parkinsonian symptoms before the next dose) and dyskinesias (involuntary choreiform movements, often at peak drug levels).$x$, 1),
('cc000000-0000-0000-0000-000000000026', 'These phenomena become more common with longer disease duration and higher cumulative levodopa exposure, and management may involve adjusting dosing frequency, adding other agents (e.g. COMT inhibitors, MAO-B inhibitors), or considering device-assisted therapies.', 2),
('cc000000-0000-0000-0000-000000000026', 'Recognising wearing-off versus dyskinesia is important because management differs: wearing-off may need more frequent/adjunctive dosing, whereas dyskinesia may need dose reduction or timing adjustment.', 3),
('cc000000-0000-0000-0000-000000000027', $x$Huntington's disease is an autosomal dominant trinucleotide (CAG) repeat disorder causing progressive chorea, along with psychiatric disturbance (irritability, depression, psychosis) and cognitive decline (subcortical dementia).$x$, 1),
('cc000000-0000-0000-0000-000000000027', 'A family history of a similarly progressive neuropsychiatric illness, especially with early death or institutionalisation, is an important clue, given the dominant inheritance pattern and genetic anticipation.', 2),
('cc000000-0000-0000-0000-000000000027', 'Genetic counselling is essential before predictive testing in at-risk relatives, given the significant psychological and social implications of a positive result for an incurable condition.', 3),
('cc000000-0000-0000-0000-000000000028', 'Acute dystonic reactions typically occur within hours to a few days of starting a dopamine-antagonist drug (antipsychotics, metoclopramide, prochlorperazine) and present with sustained abnormal postures (torticollis, oculogyric crisis, trismus).', 1),
('cc000000-0000-0000-0000-000000000028', 'Treatment is with an anticholinergic agent (e.g. procyclidine or benztropine), which usually gives rapid relief; the causative drug should also be stopped or reviewed.', 2),
('cc000000-0000-0000-0000-000000000028', 'Laryngeal/pharyngeal dystonia is a rare but dangerous complication that can compromise the airway and needs urgent recognition and treatment.', 3),
('cc000000-0000-0000-0000-000000000029', 'Optic neuritis classically presents with subacute unilateral visual loss, pain worse on eye movement, reduced colour vision, a relative afferent pupillary defect, and often a swollen optic disc (though the disc can appear normal in retrobulbar neuritis).', 1),
('cc000000-0000-0000-0000-000000000029', 'Optic neuritis is strongly associated with multiple sclerosis and may be its first clinical presentation; MRI brain and orbits can show demyelinating lesions and helps risk-stratify for future MS.', 2),
('cc000000-0000-0000-0000-000000000029', 'Management includes urgent ophthalmology/neurology referral; high-dose corticosteroids may speed visual recovery but do not alter long-term visual outcome or MS risk.', 3),
('cc000000-0000-0000-0000-000000000030', 'The McDonald criteria for MS diagnosis require evidence of central nervous system lesions disseminated in space (multiple sites, e.g. brain, spinal cord, optic nerve) and in time (lesions of different ages, or a new clinical relapse).', 1),
('cc000000-0000-0000-0000-000000000030', 'A preceding episode of optic neuritis that fully resolves is a common initial presentation of MS, particularly when followed by further relapses affecting different CNS sites.', 2),
('cc000000-0000-0000-0000-000000000030', 'Neuromyelitis optica spectrum disorder is an important differential to exclude with aquaporin-4 (and MOG) antibody testing, as management and prognosis differ significantly from MS.', 3),
('cc000000-0000-0000-0000-000000000031', $x$An MS relapse is defined as new or worsening neurological symptoms lasting more than 24 hours, in the absence of fever or infection (which can cause a 'pseudo-relapse' via worsening of old symptoms without new demyelination).$x$, 1),
('cc000000-0000-0000-0000-000000000031', 'High-dose corticosteroids (oral or IV methylprednisolone) are first-line to shorten relapse duration and severity, but do not alter long-term disability progression.', 2),
('cc000000-0000-0000-0000-000000000031', 'Infection (e.g. UTI) should always be excluded before attributing new/worsening symptoms to a true relapse, since infection can cause a temporary pseudo-relapse that resolves with treating the infection alone.', 3),
('cc000000-0000-0000-0000-000000000032', $x$Lhermitte's sign is an electric shock-like sensation radiating down the spine (and sometimes limbs) triggered by neck flexion, reflecting cervical spinal cord pathology, classically demyelination in MS.$x$, 1),
('cc000000-0000-0000-0000-000000000032', $x$Uhthoff's phenomenon (temporary worsening of MS symptoms with heat or exertion) is a different but similarly classic MS-associated phenomenon and should not be confused with Lhermitte's sign.$x$, 2),
('cc000000-0000-0000-0000-000000000032', 'Neither sign alone confirms MS, but both are useful clinical clues suggesting demyelinating disease when found in the correct context.', 3),
('cc000000-0000-0000-0000-000000000033', 'Oligoclonal bands present in CSF but not in a paired serum sample indicate intrathecal immunoglobulin synthesis and support (though are not by themselves diagnostic of) a diagnosis of multiple sclerosis.', 1),
('cc000000-0000-0000-0000-000000000033', 'CSF analysis in suspected MS is typically otherwise unremarkable (normal or mildly raised lymphocytes, normal glucose), distinguishing it from infective causes.', 2),
('cc000000-0000-0000-0000-000000000033', 'Diagnosis of MS relies on the McDonald criteria, combining clinical presentation, MRI findings of lesions disseminated in space and time, and supportive CSF findings such as oligoclonal bands.', 3),
('cc000000-0000-0000-0000-000000000034', $x$Uhthoff's phenomenon is transient worsening of existing neurological symptoms with a rise in body temperature (hot weather, exercise, fever, hot baths), which resolves as the body cools.$x$, 1),
('cc000000-0000-0000-0000-000000000034', 'It reflects impaired conduction in demyelinated axons at higher temperatures rather than new inflammatory demyelination, so it does not represent a true relapse and does not require treatment with corticosteroids.', 2),
('cc000000-0000-0000-0000-000000000034', 'Patients should be reassured and advised on practical measures (cooling strategies, avoiding excessive heat) rather than being treated as having a new relapse.', 3),
('cc000000-0000-0000-0000-000000000035', 'Neuromyelitis optica spectrum disorder classically causes severe (often bilateral) optic neuritis and longitudinally extensive transverse myelitis (3 or more vertebral segments), with aquaporin-4 (or sometimes MOG) antibodies.', 1),
('cc000000-0000-0000-0000-000000000035', 'NMOSD is a distinct disease from MS, generally with more severe individual attacks and a different long-term immunosuppressive treatment approach; it is important not to treat it with certain standard MS disease-modifying therapies, which can worsen it.', 2),
('cc000000-0000-0000-0000-000000000035', 'A relatively normal or atypical brain MRI, combined with a longitudinally extensive cord lesion and severe visual loss, should prompt aquaporin-4 antibody testing rather than assuming a diagnosis of MS.', 3),
('cc000000-0000-0000-0000-000000000036', 'Guillain-Barre syndrome typically presents as an ascending, symmetrical, predominantly motor polyneuropathy with areflexia, often 1-3 weeks after an infection (classically Campylobacter jejuni gastroenteritis).', 1),
('cc000000-0000-0000-0000-000000000036', 'Regular FVC monitoring is essential because respiratory muscle weakness can progress rapidly and unpredictably; a falling FVC (or values below roughly 15-20 mL/kg) should prompt urgent critical care/anaesthetic involvement for possible ventilatory support.', 2),
('cc000000-0000-0000-0000-000000000036', 'Autonomic dysfunction (arrhythmias, labile blood pressure) is another important complication requiring monitoring in Guillain-Barre syndrome.', 3),
('cc000000-0000-0000-0000-000000000037', 'Myasthenia gravis causes fatigable weakness that worsens with sustained or repeated activity and improves with rest, classically affecting ocular (ptosis, diplopia), bulbar, and proximal limb muscles.', 1),
('cc000000-0000-0000-0000-000000000037', 'Sensation and reflexes are typically preserved in myasthenia gravis, helping distinguish it from other neuromuscular and peripheral nerve conditions.', 2),
('cc000000-0000-0000-0000-000000000037', 'Myasthenic crisis (severe weakness causing respiratory failure) is a medical emergency; bulbar or respiratory symptoms in myasthenia gravis require urgent assessment of swallowing and ventilatory function.', 3),
('cc000000-0000-0000-0000-000000000038', 'Myasthenic crisis is a life-threatening exacerbation of myasthenia gravis with respiratory and/or bulbar weakness, often triggered by infection, surgery, or certain drugs (aminoglycosides and some other antibiotics can worsen neuromuscular transmission).', 1),
('cc000000-0000-0000-0000-000000000038', 'Falling vital capacity and bulbar symptoms (dysphagia, dysarthria) are red flags requiring urgent critical care involvement and consideration of ventilatory support before respiratory arrest occurs.', 2),
('cc000000-0000-0000-0000-000000000038', 'Specific treatments for myasthenic crisis include IVIG or plasma exchange, with specialist neurology/critical care input; the underlying trigger (e.g. infection) should also be treated.', 3),
('cc000000-0000-0000-0000-000000000039', 'Carpal tunnel syndrome causes median nerve compression at the wrist, producing numbness/tingling in the thumb, index, middle, and radial half of the ring finger, classically worse at night and relieved by shaking the hand.', 1),
('cc000000-0000-0000-0000-000000000039', 'Thenar wasting and weak thumb abduction/opposition indicate more advanced median nerve compression and support the diagnosis, as well as being an indication for surgical referral.', 2),
('cc000000-0000-0000-0000-000000000039', 'Risk factors include repetitive hand use/occupational strain, pregnancy, hypothyroidism, diabetes, and rheumatoid arthritis; management ranges from wrist splinting and corticosteroid injection to surgical decompression in persistent or severe cases.', 3),
('cc000000-0000-0000-0000-000000000040', 'Motor neurone disease characteristically causes a combination of upper motor neuron signs (spasticity, brisk reflexes, extensor plantar responses) and lower motor neuron signs (wasting, fasciculations, weakness) with entirely normal sensation.', 1),
('cc000000-0000-0000-0000-000000000040', 'Bulbar involvement (dysphagia, dysarthria) indicates bulbar-onset or bulbar-involved disease and raises concern about aspiration risk, requiring speech and language therapy/swallowing assessment.', 2),
('cc000000-0000-0000-0000-000000000040', 'There is no sensory involvement in motor neurone disease; any significant sensory findings should prompt reconsideration of the diagnosis and search for an alternative cause.', 3),
('cc000000-0000-0000-0000-000000000041', $x$Diabetic peripheral neuropathy typically causes a symmetrical, distal, sensory-predominant polyneuropathy in a 'glove and stocking' distribution, often with burning night pain and loss of ankle reflexes.$x$, 1),
('cc000000-0000-0000-0000-000000000041', 'Poor glycaemic control (reflected by a high HbA1c) over a long disease duration is a major risk factor; good glycaemic control can slow progression.', 2),
('cc000000-0000-0000-0000-000000000041', 'Loss of protective sensation increases the risk of unnoticed foot trauma and ulceration, making regular diabetic foot screening and patient education about foot care essential.', 3),
('cc000000-0000-0000-0000-000000000042', $x$Bell's palsy causes a unilateral lower motor neuron facial palsy affecting the forehead (unable to wrinkle it) as well as the lower face, distinguishing it from a central (stroke-related) facial palsy, which spares the forehead.$x$, 1),
('cc000000-0000-0000-0000-000000000042', 'Prompt treatment with oral corticosteroids (ideally within 72 hours of onset) improves the chance of full recovery; eye care (lubricating drops, taping at night) is essential to prevent exposure keratopathy if the eye cannot close fully.', 2),
('cc000000-0000-0000-0000-000000000042', $x$Any other cranial nerve involvement, limb weakness, or systemic features should prompt reconsideration of alternative diagnoses (e.g. stroke, Lyme disease, tumour) rather than assuming idiopathic Bell's palsy.$x$, 3),
('cc000000-0000-0000-0000-000000000043', 'FAST (Face, Arm, Speech, Time) recognition of stroke symptoms should prompt an emergency ambulance call and urgent hospital assessment; time from onset determines eligibility for time-critical reperfusion therapies.', 1),
('cc000000-0000-0000-0000-000000000043', 'IV thrombolysis (alteplase, or alternatives such as tenecteplase) is generally given within 4.5 hours of symptom onset for ischaemic stroke without contraindications, after CT has excluded haemorrhage.', 2),
('cc000000-0000-0000-0000-000000000043', 'Mechanical thrombectomy should be considered in patients with a confirmed large vessel occlusion, and can be combined with thrombolysis or used alone in certain circumstances/time windows.', 3),
('cc000000-0000-0000-0000-000000000044', 'TIA is defined as a transient episode of neurological dysfunction due to focal brain ischaemia, with complete resolution of symptoms, but it is a strong warning sign requiring urgent action given the high early risk of a subsequent stroke.', 1),
('cc000000-0000-0000-0000-000000000044', 'Aspirin 300 mg should be given immediately after a suspected TIA (once haemorrhage is considered unlikely/excluded) and urgent specialist assessment within 24 hours is required to look for underlying causes (e.g. carotid stenosis, atrial fibrillation) and guide secondary prevention.', 2),
('cc000000-0000-0000-0000-000000000044', 'Driving restrictions and safety advice (not to drive until assessed) are also important considerations after a TIA.', 3),
('cc000000-0000-0000-0000-000000000045', 'Significant symptomatic carotid artery stenosis (generally >50-70% depending on criteria) ipsilateral to the stroke/TIA is an indication for carotid endarterectomy, which reduces the risk of future stroke.', 1),
('cc000000-0000-0000-0000-000000000045', 'Endarterectomy is most beneficial when performed promptly, ideally within 2 weeks of the qualifying event, in patients fit for surgery.', 2),
('cc000000-0000-0000-0000-000000000045', 'Secondary prevention after ischaemic stroke also includes antiplatelet therapy, statin therapy, and optimisation of vascular risk factors (blood pressure, diabetes, smoking cessation), alongside addressing carotid disease.', 3),
('cc000000-0000-0000-0000-000000000046', 'Intracerebral haemorrhage is a neurosurgical emergency; CT head distinguishes it from ischaemic stroke and dictates completely different management (no thrombolysis, no antiplatelets/anticoagulants).', 1),
('cc000000-0000-0000-0000-000000000046', 'Acute blood pressure control (per current stroke guidelines) is a key intervention in intracerebral haemorrhage to reduce the risk of haematoma expansion, alongside reversal of any anticoagulation if present.', 2),
('cc000000-0000-0000-0000-000000000046', 'Reduced GCS, midline shift, or signs of raised intracranial pressure should prompt urgent neurosurgical assessment for possible surgical evacuation or intracranial pressure management.', 3),
('cc000000-0000-0000-0000-000000000047', 'After ischaemic stroke, once haemorrhage is excluded, aspirin 300 mg daily is given for 2 weeks (or until discharge if earlier), followed by long-term secondary prevention typically with clopidogrel 75 mg daily.', 1),
('cc000000-0000-0000-0000-000000000047', 'Swallowing must be formally assessed before giving oral medication after a stroke, as dysphagia is common and increases aspiration risk; alternative routes (e.g. rectal or NG) are used if swallowing is unsafe.', 2),
('cc000000-0000-0000-0000-000000000047', 'Routine early anticoagulation is generally avoided after ischaemic stroke due to bleeding risk, even in patients with atrial fibrillation, where anticoagulation is typically delayed and initiated after a period of days depending on infarct size and haemorrhagic transformation risk.', 3),
('cc000000-0000-0000-0000-000000000048', $x$Lateral medullary (Wallenberg) syndrome results from posterior inferior cerebellar artery occlusion and classically causes crossed sensory loss: ipsilateral facial pain/temperature loss with contralateral body pain/temperature loss, plus ipsilateral ataxia, vertigo, nystagmus, dysphagia, and Horner's syndrome.$x$, 1),
('cc000000-0000-0000-0000-000000000048', $x$Posterior circulation strokes often present with the classic 'D' symptoms: diplopia, dysarthria, dysphagia, dizziness/vertigo, and ataxia, which can be easily missed if not specifically considered.$x$, 2),
('cc000000-0000-0000-0000-000000000048', 'Recognising posterior circulation stroke syndromes is important as these can be more subtle than anterior circulation strokes but carry significant risks, including brainstem compression and hydrocephalus with cerebellar infarcts.', 3),
('cc000000-0000-0000-0000-000000000049', 'Thrombolysis eligibility depends on time since onset, absence of haemorrhage on CT, and coagulation status (an INR above a defined threshold, generally around 1.7, is a contraindication) rather than simply a history of anticoagulant use.', 1),
('cc000000-0000-0000-0000-000000000049', 'A mechanical heart valve is a strong risk factor for cardioembolic stroke, and long-term anticoagulation is essential; poor adherence (as here) is an important and common precipitant of stroke that should be addressed once the acute event is managed.', 2),
('cc000000-0000-0000-0000-000000000049', 'Restarting/optimising anticoagulation after an acute stroke in a patient with a mechanical valve needs careful specialist timing to balance haemorrhagic transformation risk against recurrent thromboembolism risk.', 3),
('cc000000-0000-0000-0000-000000000050', 'Cerebral venous sinus thrombosis should be considered in patients (especially postpartum women, or those on the combined oral contraceptive pill, or with other prothrombotic states) presenting with headache, seizures, and focal neurological deficits.', 1),
('cc000000-0000-0000-0000-000000000050', 'MR or CT venography is used to confirm the diagnosis by demonstrating a filling defect in the venous sinus.', 2),
('cc000000-0000-0000-0000-000000000050', 'Anticoagulation is the mainstay of treatment, even in the presence of an associated venous infarct (which may have haemorrhagic elements), distinguishing management from arterial stroke.', 3);
